"""Original MAC APS learning resources, October 2026.

This authoring file produces supplementary preparation/revision resources.
It never establishes attendance, an SST certificate, or regulatory MAC credit.
"""
from __future__ import annotations
import json
from pathlib import Path

LESSONS = []
BASE = 'https://www.legifrance.gouv.fr/loda/id/JORFTEXT000034104578/'
INRS = 'https://www.inrs.fr/media.html?refINRS=ED+4085'
SECOURS = 'https://www.inrs.fr/demarche/organisation-secours/accident-malaise.html'
DEONTO = 'https://www.legifrance.gouv.fr/codes/section_lc/LEGITEXT000025503132/LEGISCTA000029656370/'
FILTRAGE = 'https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000054725427'
VIGI = 'https://www.sgdsn.gouv.fr/vigipirate'
REFLEXES = 'https://www.sgdsn.gouv.fr/vigipirate/les-fiches-de-recommandations-et-de-bonnes-pratiques'
ATTAQUE = 'https://www.info.gouv.fr/risques/reagir-en-cas-dattaque-terroriste'
CONFLITS = 'https://www.inrs.fr/risques/agressions-violences-externes/prevention.html'


def sec(heading, text):
    return {'heading': heading, 'paragraphs': [p.strip() for p in text.strip().split('\n\n') if p.strip()]}


def example(title, text):
    return {'title': title, 'paragraphs': [p.strip() for p in text.strip().split('\n\n') if p.strip()]}


def question(prompt, correct, wrong1, wrong2, explanation):
    return (prompt, correct, wrong1, wrong2, explanation)


def add(module, number, title, objective, mode, sources, sections, worked, columns, rows, takeaways, scenario_title, intro, decisions, questions):
    ident = f'macaps-{module}-{number:02}'
    def build(row, index, kind):
        prompt, correct, wrong1, wrong2, explanation = row
        variants = [correct, wrong1, wrong2]
        shift = (number + index + int(module)) % 3
        variants = variants[shift:] + variants[:shift]
        options = [{'id': chr(97+i), 'text': text} for i, text in enumerate(variants)]
        return {'id': f'{ident}-{kind}{index+1}', 'prompt': prompt, 'options': options,
                'answer': next(o['id'] for o in options if o['text'] == correct), 'explanation': explanation}
    LESSONS.append({'id': ident, 'module': module, 'title': title, 'objective': objective,
                    'mode': mode, 'source_urls': list(dict.fromkeys([BASE, *sources])),
                    'sections': sections, 'example': worked, 'table': {'headers': columns, 'rows': rows},
                    'takeaways': takeaways, 'scenario': {'title': scenario_title, 'intro': intro,
                    'steps': [build(q,i,'s') for i,q in enumerate(decisions)]},
                    'quiz': [build(q,i,'q') for i,q in enumerate(questions)]})


add('01', 1, 'Protéger et organiser les secours',
    'Repérer les dangers persistants, choisir une protection adaptée et déclencher les secours sans retarder une action urgente.',
    'presentiel_preparation', [INRS, SECOURS], [
    sec('Repartir de la situation réelle', """Une intervention de secours commence par ce qui se passe autour de la victime. Votre expérience du site constitue un avantage si elle vous aide à repérer une circulation, une machine, une alimentation électrique, des fumées ou une violence encore présente. Elle devient un piège si elle vous fait supposer que le danger a déjà disparu. Arrêtez-vous à une position sûre, identifiez les personnes exposées et demandez une information courte à un témoin. La protection concerne la victime, les témoins et vous-même : un second accident réduit les moyens disponibles pour tout le monde.

Le raisonnement consiste à supprimer le danger lorsque cela est possible dans vos compétences, à l'isoler ou à empêcher l'exposition. Une commande d'arrêt connue et accessible peut être utilisée selon les consignes ; pénétrer dans un local enfumé ou intervenir sur une installation électrique ne relève pas d'une simple initiative de secours. Si le danger persiste, empêchez l'accès depuis une position sûre et décrivez-le aux services spécialisés. Un déplacement de victime reste exceptionnel, face à un danger réel, immédiat et non maîtrisable, avec un accès et un trajet de retrait possibles sans vous exposer."""),
    sec('Votre rôle et vos limites', """L'obligation d'assistance ne demande pas de réaliser une action qui créerait un risque pour vous-même ou pour des tiers. Elle implique de ne pas rester passif : provoquer les secours, organiser l'accueil, éloigner des personnes ou effectuer un geste appris peut constituer l'assistance adaptée. Expliquez votre intervention à une victime consciente, recherchez sa coopération et respectez sa dignité. L'agent n'établit pas un diagnostic médical ; il décrit des signes, applique ses compétences actualisées et suit les instructions de la régulation des secours.

Le présent support prépare les échanges et les exercices avec le formateur. Il ne renouvelle pas un certificat SST et ne constate pas la réalisation du module pratique. Le module réglementaire de gestes élémentaires représente sept heures. Une éventuelle dispense repose sur les justificatifs admis par le texte, à la demande du stagiaire et après vérification par l'organisme. Le questionnaire pédagogique du site ne remplace pas cette décision. Même dispensé de ce module, vous restez concerné par les objectifs de secours liés à une attaque du module terrorisme."""),
    sec('Alerter et répartir des tâches précises', """Déclenchez l'alerte interne prévue sur le site sans la confondre avec l'appel aux secours publics. Faites connaître le lieu exact, l'accès utilisable, la nature de l'accident, les dangers persistants, le nombre de personnes et les signes observés. Le 15 répond à l'urgence médicale, le 18 aux secours des sapeurs-pompiers et le 112 permet de joindre les services d'urgence. Si vous déléguez l'appel, désignez une personne et demandez-lui de confirmer qu'il a été effectué. Plusieurs témoins présents ne signifient pas que quelqu'un a effectivement appelé.

Préparez le relais dès les premières minutes. Un collègue peut guider les secours depuis le portail, un autre apporter le matériel disponible, tandis que vous restez auprès de la victime. La répartition doit préserver l'accès et éviter l'attroupement. Notez mentalement les horaires utiles, surveillez toute évolution et transmettez-la. Après l'intervention, le compte rendu distingue les circonstances connues, les observations et les actions réalisées. La remontée d'un défaut de protection permet ensuite d'éviter la répétition de l'accident."""),
    ], example('Un accident au quai de livraison', """À la prise de poste, vous découvrez un livreur au sol près d'un quai. Un chariot circule encore et deux témoins se précipitent vers lui. Vous faites interrompre la circulation par le responsable de zone, gardez les témoins hors de la trajectoire et vérifiez que l'approche est sûre. Vous désignez un collègue pour l'appel et un autre pour l'accueil au portail logistique.

L'information « entrepôt, porte nord » reste trop vague lorsque le site possède trois quais. Vous précisez le numéro du bâtiment, l'accès ouvert et l'existence d'une rampe. Vous examinez ensuite les signes utiles sans chercher à reconstituer l'accident avant de secourir. L'enquête sur la chute viendra après la prise en charge."""),
    ['Point à contrôler', 'Décision attendue'], [
        ['Danger encore présent', 'Supprimer dans ses compétences, isoler ou empêcher l’exposition.'],
        ['Appel délégué', 'Nommer un témoin, préciser le message et demander confirmation.'],
        ['Secours en approche', 'Préserver un accès identifiable et organiser leur guidage.'],
        ['Après la prise en charge', 'Tracer les faits utiles et signaler les causes de risque.']],
    ['Une approche sûre précède les gestes.', 'Une tâche déléguée doit être confirmée.', 'Les consignes internes complètent l’alerte aux secours publics.', 'Un parcours numérique ne valide pas les gestes en situation.'],
    'Le quai reste en activité', 'Un transporteur est tombé pendant une livraison et un engin continue à manœuvrer.', [
        question('Que faites-vous d’abord ?', 'Faire interrompre le mouvement et empêcher une nouvelle exposition.', 'Traverser immédiatement la trajectoire pour rejoindre le transporteur.', 'Commencer le compte rendu avant de modifier la circulation.', 'La protection doit empêcher le suraccident avant l’approche.'),
        question('Votre collègue dit : « quelqu’un va appeler ». Quelle réponse est utile ?', 'Le désigner pour appeler et lui demander de confirmer le contact.', 'Considérer que la présence de témoins garantit l’alerte.', 'Attendre que le transporteur demande lui-même les secours.', 'Une responsabilité attribuée évite les appels supposés mais jamais réalisés.'),
        question('Les secours annoncent leur arrivée. Quelle tâche déléguez-vous ?', 'Le guidage par l’accès logistique praticable, en maintenant la protection.', 'La reprise des livraisons pour libérer plus vite le quai.', 'Le déplacement systématique de la victime vers le parking.', 'Le guidage facilite la prise en charge sans exposer ni déplacer inutilement la victime.')], [
        question('Que transmet-on en priorité sur le lieu ?', 'L’adresse précise et l’accès réellement utilisable.', 'Seulement le nom commercial du site.', 'Le planning complet de l’équipe.', 'Les secours doivent localiser la victime et entrer sans perdre de temps.'),
        question('Un risque électrique reste présent. Quelle limite s’impose ?', 'Ne pas intervenir sur l’installation hors de ses compétences.', 'Toucher la victime pour tester si le courant circule.', 'Employer un objet improvisé sans évaluer le danger.', 'L’agent ne doit pas devenir une seconde victime ; il alerte et protège.'),
        question('Que prouve la lecture de cette leçon ?', 'Une consultation de préparation pédagogique.', 'Le renouvellement automatique du SST.', 'La réalisation des sept heures réglementaires de gestes.', 'La lecture ne constitue ni une certification SST ni une évaluation pratique.')])

add('01', 2, 'Reconnaître un saignement abondant ou un étouffement',
    'Identifier deux urgences vitales visibles et comprendre les décisions qui seront entraînées avec le formateur.',
    'presentiel_preparation', [INRS, 'https://www.ameli.fr/assure/sante/urgence/corps-etrangers/inhale'], [
    sec('Observer une urgence sans attendre son aggravation', """Un saignement abondant qui ne s'arrête pas menace rapidement la victime. Il peut être visible sur le sol, les vêtements ou une surface de travail ; son origine n'est pas toujours immédiatement évidente. Ne perdez pas du temps à mesurer un volume de sang. Après protection, repérez l'endroit qui saigne, faites alerter et engagez l'action de secours que vous maîtrisez. L'objectif est d'arrêter le saignement, de surveiller la victime et de préparer le relais. Une personne encore capable de parler peut néanmoins se dégrader.

La compression directe est la réponse de référence lorsque la situation le permet, avec une protection contre le contact avec le sang. Une victime consciente peut contribuer en comprimant elle-même sa plaie sur votre indication. Un objet fiché ne doit pas être retiré, ni une plaie explorée. Certaines situations empêchent ou rendent inefficace la compression : le choix d'un autre moyen, dont le garrot lorsque son indication est réunie, se travaille avec un formateur et du matériel adapté. On ne desserre pas un garrot posé en attendant les secours ; l'heure de pose doit leur être communiquée."""),
    sec('Distinguer toux efficace et obstruction grave', """Face à une personne qui semble s'étouffer pendant un repas, commencez par rechercher si elle peut parler, tousser efficacement et respirer. Une toux efficace indique que de l'air circule encore : encouragez-la à tousser et surveillez-la, sans réaliser de manœuvre d'expulsion qui pourrait aggraver l'obstruction. Ne donnez ni boisson ni aliment pour « faire passer ». Si la toux devient inefficace, si la personne ne peut plus parler ou respirer, la situation exige les gestes de désobstruction appris et une alerte immédiate.

Les gestes varient selon la victime, notamment adulte, enfant, nourrisson ou personne nécessitant une adaptation. C'est précisément l'intérêt de l'entraînement présentiel : position, intensité, limites et changement de conduite lorsque la victime perd connaissance. Le module numérique vous entraîne à reconnaître la bonne branche de décision. Il ne vous demande jamais de tester une compression abdominale ou une manœuvre sur un proche pour réussir une activité. Une perte de connaissance impose une réévaluation de la respiration et un basculement vers la conduite adaptée, guidée si nécessaire par les secours."""),
    sec('Coordonner sans interrompre le secours', """Dans un restaurant, un magasin ou un événement, la difficulté vient souvent de l'attroupement. Demandez à une personne précise d'appeler et à une autre de libérer l'espace. Parlez avec des phrases courtes : nature du problème, tâche à réaliser, confirmation attendue. Évitez les annonces de diagnostic et les commentaires alarmants. Vous pouvez dire qu'une personne saigne abondamment ou n'arrive plus à respirer. Restez concentré sur les signes et vérifiez l'efficacité de l'action. Une amélioration ne dispense pas de suivre les consignes médicales.

Après les gestes, la transmission doit décrire le problème initial, les changements constatés, les actions et leur heure approximative. L'exposition au sang, le matériel utilisé ou un contact accidentel doivent être signalés selon la procédure de l'entreprise. L'analyse ultérieure porte aussi sur l'accessibilité du matériel, la qualité de l'alerte et la coordination de l'équipe. Elle ne transforme pas la victime en objet de démonstration : aucune image ne doit être prise pour illustrer l'incident dans un groupe de messagerie."""),
    ], example('Deux urgences, deux raisonnements', """Au restaurant du site, un salarié tousse fortement après avoir avalé. Il répond quand vous lui parlez. Vous l'encouragez à continuer de tousser, restez à proximité et surveillez son état. Votre collègue propose immédiatement une manœuvre : vous rappelez que les signes doivent guider la décision, et non le seul mot « étouffement » crié par un témoin.

Une semaine plus tard, un prestataire se blesse à la main et le sang coule sans s'arrêter. Vous protégez l'approche, faites appeler les secours et appliquez la conduite correspondant au saignement abondant. Le dialogue calme reste utile, mais ne remplace pas le geste urgent. Dans les deux cas, l'efficacité se juge sur l'évolution observable."""),
    ['Signe observé', 'Priorité de raisonnement'], [
        ['Saignement abondant persistant', 'Arrêter le saignement, alerter et surveiller.'],
        ['Toux efficace et parole possible', 'Encourager la toux, surveiller, ne pas faire de manœuvre d’expulsion.'],
        ['Impossible de parler ou de respirer', 'Désobstruction adaptée apprise et alerte.'],
        ['Perte de connaissance', 'Réévaluer la respiration et adapter immédiatement la conduite.']],
    ['Les signes orientent l’action, pas le diagnostic d’un témoin.', 'Une toux efficace doit être respectée.', 'Ne retirez pas un objet fiché dans une plaie.', 'Les gestes et adaptations se répètent sous supervision.'],
    'Incident au restaurant', 'Une personne porte la main à sa gorge, tousse puis voit son état changer.', [
        question('Elle tousse fortement et répond à votre question. Que retenez-vous ?', 'L’air circule encore ; encourager la toux et surveiller.', 'Toute toux exige des compressions immédiates.', 'La parole garantit qu’aucune surveillance n’est utile.', 'La toux efficace conduit à surveiller, sans manœuvre d’expulsion.'),
        question('Elle ne peut désormais plus parler ni respirer. Quelle évolution identifiez-vous ?', 'Une obstruction grave nécessitant les gestes appris et l’alerte.', 'Une simple gêne résolue par une boisson.', 'Une situation à filmer pour la transmettre au responsable.', 'L’absence de respiration et de parole fait changer immédiatement la conduite.'),
        question('Les secours arrivent. Quelle transmission est utile ?', 'Les signes successifs, les gestes réalisés et l’évolution.', 'Uniquement le menu servi au repas.', 'Une affirmation sur la maladie supposée de la personne.', 'La chronologie des signes et actions aide le relais médical.')], [
        question('Un objet est fiché dans une plaie. Que faut-il éviter ?', 'Le retirer pour voir la profondeur.', 'Décrire ce que l’on voit aux secours.', 'Protéger les personnes autour.', 'Retirer un objet fiché peut aggraver la lésion ou le saignement.'),
        question('Quel élément doit accompagner la transmission d’un garrot posé ?', 'L’heure de pose.', 'La marque de la tenue de l’agent.', 'Le motif commercial de présence de la victime.', 'L’heure de pose constitue une information essentielle pour les secours.'),
        question('Où répéter les gestes de désobstruction ?', 'Dans les ateliers adaptés encadrés par le formateur.', 'Sur un collègue sans encadrement pour valider la page.', 'Sur une personne qui tousse normalement pour tester la technique.', 'L’apprentissage des gestes doit être sécurisé et supervisé.')])

add('01', 3, 'Vérifier la conscience et la respiration, préparer le DAE',
    'Distinguer les situations liées à la conscience et à la respiration, puis organiser une réanimation et un relais adaptés.',
    'presentiel_preparation', [INRS, 'https://www.ameli.fr/assure/sante/urgence/pathologies/infarctus-myocarde-reagir'], [
    sec('Une personne immobile n’est pas un diagnostic', """Une personne au sol peut présenter des situations très différentes. Après protection et recherche d'une urgence évidente, vérifiez sa réponse par des demandes simples et un contact adapté. Si elle ne répond pas, recherchez la respiration selon la méthode actualisée enseignée en formation. Une respiration absente, très anormale ou réduite à des mouvements inefficaces n'est pas une respiration normale. Le doute doit être annoncé au régulateur afin de recevoir une aide immédiate. Ne perdez pas de temps à chercher un pouls si ce geste ne relève pas de votre formation.

Si la personne ne répond pas mais respire normalement, l'action vise à maintenir la liberté des voies aériennes et à surveiller. Les recommandations actualisées distinguent la cause non traumatique de la situation traumatique ou d'origine inconnue : une position latérale n'est pas à appliquer systématiquement à toute victime inconsciente. En cas de traumatisme ou d'origine inconnue, les précautions de positionnement et de maintien des voies aériennes sont entraînées avec le formateur et adaptées aux instructions des secours. La surveillance de la respiration reste continue, car l'état peut évoluer."""),
    sec('L’absence de respiration normale commande une action immédiate', """Lorsqu'une victime ne répond pas et ne respire pas normalement, faites alerter les secours et demander le défibrillateur disponible. Commencez la réanimation conformément à vos compétences et aux consignes de la régulation. Les compressions thoraciques doivent être engagées sans attendre que le matériel traverse tout le site. Le formateur contrôle la position, le rythme, la profondeur, le relâchement, les interruptions et l'articulation avec les insufflations selon l'âge de la victime et le référentiel en vigueur. Les adaptations enfant et nourrisson ne doivent pas être déduites au hasard de la technique adulte.

Le défibrillateur automatisé externe guide l'utilisateur par des consignes. Une fois disponible, mettez-le en œuvre et respectez les indications de l'appareil. Pendant une analyse ou un choc, personne ne doit toucher la victime. En dehors des interruptions nécessaires, les gestes de réanimation se poursuivent selon les instructions. L'appareil ne remplace ni l'alerte ni les compressions. L'agent qui connaît le lieu du DAE, ses conditions d'accès et l'itinéraire pour l'apporter réduit un délai concret sans avoir besoin d'établir un diagnostic médical."""),
    sec('Faire fonctionner l’équipe', """En situation réelle, donnez à chacun une tâche identifiable : alerter, chercher le DAE, accueillir les secours, préserver l'espace ou préparer un relais sur les compressions. Un collègue entraîné peut prendre le relais pour maintenir la qualité des gestes ; ce changement doit limiter les interruptions. La communication doit rester simple et audible. Éloignez les curieux sans isoler l'intervenant de toute aide. Si vous êtes seul, le régulateur peut vous aider à organiser les priorités avec le téléphone en haut-parleur lorsque cela est possible.

La préparation au poste comprend une vérification concrète de l'organisation : qui possède la clé d'un meuble éventuel, le DAE reste-t-il accessible après la fermeture, l'adresse d'appel figure-t-elle sur le poste, un badge est-il nécessaire pour rejoindre la victime ? Un matériel « présent dans le bâtiment » mais inaccessible la nuit ne constitue pas une réponse satisfaisante. Signalez ces obstacles avant un accident. Après la prise en charge, protégez la confidentialité, reconstituez les horaires utiles et participez au retour d'expérience de l'équipe."""),
    ], example('Malaise dans un hall d’entreprise', """Un visiteur s'effondre dans le hall. Votre collègue reste figé devant le téléphone du standard. Après protection, vous constatez qu'il ne répond pas et ne respire pas normalement. Vous lui donnez une consigne nominative : appeler les secours, mettre le téléphone sur haut-parleur puis indiquer l'entrée du hall. Un second témoin est envoyé chercher le DAE connu au rez-de-chaussée.

Vous engagez les gestes appris. Quand le DAE arrive, chacun écoute ses indications, personne ne touche la victime pendant l'analyse et le relais s'organise sans discussions annexes. L'exercice avec le formateur permettra de contrôler précisément vos gestes ; le cas en ligne vérifie votre capacité à distribuer les tâches dans le bon ordre."""),
    ['Observation ou moyen', 'Ce que cela implique'], [
        ['Aucune réponse', 'Rechercher la respiration suivant la méthode apprise.'],
        ['Absence de respiration normale', 'Alerter, réanimer et utiliser le DAE dès sa disponibilité.'],
        ['Respiration normale, cause incertaine', 'Protéger les voies aériennes, limiter les mouvements et suivre les secours.'],
        ['DAE en phase d’analyse ou de choc', 'Ne pas toucher la victime et écouter les consignes.']],
    ['Une respiration anormale ne rassure pas.', 'Le DAE complète les gestes de réanimation.', 'La position d’attente dépend aussi du contexte traumatique.', 'Prévoir un accès au DAE pour chaque horaire du site.'],
    'Le DAE est dans un autre bâtiment', 'Un visiteur inconscient ne respire pas normalement ; le défibrillateur se trouve à plusieurs minutes.', [
        question('Quelle décision prend-on sans attendre son arrivée ?', 'Alerter et commencer la réanimation selon les compétences et les consignes.', 'Attendre le DAE avant tout geste.', 'Déplacer la victime jusqu’au local du DAE.', 'Le délai d’arrivée du matériel ne doit pas retarder la réanimation.'),
        question('Le DAE annonce une analyse. Que fait l’équipe ?', 'Elle s’écarte du contact avec la victime et suit les indications.', 'Elle continue à toucher la victime pour la rassurer.', 'Elle débranche l’appareil pour écouter le téléphone.', 'L’absence de contact pendant l’analyse et le choc fait partie des consignes essentielles.'),
        question('Après l’intervention, quelle amélioration concerne le site ?', 'Vérifier l’accessibilité et le temps d’acheminement du DAE sur tous les horaires.', 'Déplacer tout le matériel sans consulter l’organisation du site.', 'Conserver la porte fermée sans identifier les détenteurs de clé.', 'Le retour d’expérience permet de réduire les obstacles concrets à l’utilisation du matériel.')], [
        question('Une victime ne répond pas et respire de façon très anormale. Que faut-il éviter ?', 'Considérer cette respiration comme rassurante.', 'Préciser les signes au régulateur.', 'Demander le DAE disponible.', 'Des mouvements respiratoires anormaux ne permettent pas d’exclure l’arrêt cardiaque.'),
        question('La position latérale doit-elle être systématique pour toute inconscience ?', 'Non, le contexte traumatique et les consignes actualisées comptent.', 'Oui, sans tenir compte d’une chute ou d’une cause inconnue.', 'Oui, avant toute recherche de respiration.', 'Les recommandations distinguent notamment les situations non traumatiques des traumatismes ou origines inconnues.'),
        question('Quelle activité nécessite le contrôle du formateur ?', 'La qualité des compressions et les adaptations à l’âge.', 'La lecture de l’adresse du site.', 'La consultation du plan d’accès.', 'La maîtrise gestuelle se vérifie sur du matériel adapté en présentiel.')])

add('01', 4, 'Prendre en charge malaises, brûlures et traumatismes',
    'Reconnaître les signes nécessitant une alerte, éviter les gestes aggravants et transmettre l’évolution de la victime.',
    'presentiel_preparation', [INRS, 'https://www.ameli.fr/assure/sante/urgence/accidents-domestiques/brulures-peau', 'https://www.ameli.fr/assure/sante/urgence/accidents-domestiques/electrisation-electrocution'], [
    sec('Écouter un malaise sans le banaliser', """L'agent voit parfois une personne pâle, essoufflée, confuse ou douloureuse au poste d'accueil. Ne ramenez pas immédiatement ces signes à la fatigue, à l'âge, à l'alcool ou au stress. Demandez ce qu'elle ressent, depuis quand et si l'état change. Une douleur thoracique, une difficulté respiratoire, une faiblesse soudaine d'un côté, une déformation du visage ou un trouble brutal de la parole exigent une alerte rapide. L'absence de blessure visible ne signifie pas absence d'urgence. Le rôle de l'agent est d'observer et de transmettre, non de choisir une cause rassurante.

Mettez la personne au repos dans une position adaptée à son état et à ses souhaits, protégez-la des regards et appelez selon l'organisation des secours. Ne la faites pas marcher jusqu'au parking ou repartir seule pour « prendre l'air ». Recherchez les informations utiles sans prolonger un interrogatoire : symptômes, début, antécédents ou traitement qu'elle peut spontanément préciser. Ne donnez pas un médicament personnel ou une boisson par habitude. La régulation médicale décide de la réponse ; restez auprès de la personne et signalez toute modification de conscience ou de respiration."""),
    sec('Refroidir une brûlure et ne pas aggraver la lésion', """Après suppression du danger, une brûlure thermique se refroidit rapidement avec de l'eau courante tempérée, en suivant les consignes actualisées et médicales. Évitez la glace, les corps gras et les produits improvisés. Les vêtements collés ne sont pas arrachés. La gravité dépend notamment de l'étendue, de la localisation, de la profondeur supposée, de l'âge et du mécanisme. En cas de doute, de brûlure importante ou de localisation préoccupante, faites demander un avis médical. Il faut protéger la victime du refroidissement général tout en poursuivant la conduite adaptée à la zone brûlée.

Une origine chimique ou électrique impose d'abord de traiter le danger spécifique. Ne touchez pas une victime encore en contact avec une source électrique. Une petite marque visible après électrisation ne reflète pas nécessairement les lésions internes : l'alerte et l'évaluation médicale sont nécessaires. Face à un produit chimique, protégez-vous, évitez de vous contaminer et transmettez le nom du produit si vous pouvez l'obtenir sans risque. N'improvisez pas une neutralisation chimique. Les procédures particulières, les équipements de protection et les modalités de rinçage se préparent avec les personnes compétentes du site."""),
    sec('Préserver une victime de traumatisme', """Après une chute ou un choc, demandez à la victime de ne pas bouger si elle se plaint du dos, du cou, de la tête ou d'un membre. Ne testez pas sa capacité à marcher et ne tentez pas de remettre une articulation en place. Laissez la zone dans la position trouvée dans la mesure du possible et suivez les secours. Le déplacement n'est envisagé qu'en présence d'un danger imposant un retrait d'urgence, selon les principes appris. Un casque ou un équipement ne se retire pas par curiosité ; les gestes qui pourraient mobiliser la victime relèvent d'une conduite adaptée.

La surveillance se poursuit jusqu'au relais. Une personne peut d'abord répondre correctement, puis devenir somnolente ou présenter une difficulté respiratoire. Prévenez immédiatement le régulateur d'une évolution. À l'arrivée des secours, transmettez le mécanisme connu, les plaintes, les signes observés, les actions et les changements. Dans votre trace professionnelle, évitez les diagnostics définitifs : écrivez « douleur au poignet après chute », pas « fracture certaine ». La remise en sécurité de la zone et la prévention d'un nouvel accident se conduisent en parallèle de la prise en charge."""),
    ], example('Une chute pendant une ronde accompagnée', """Un salarié glisse dans un escalier humide pendant que vous contrôlez une issue. Il répond, mais se plaint du dos. Vous empêchez le passage sur la marche glissante, faites alerter et lui demandez de rester immobile. Un collègue veut l'asseoir pour dégager l'escalier : vous maintenez la protection de la zone et attendez les consignes médicales.

Quelques minutes plus tard, la personne devient moins réactive. Vous transmettez immédiatement ce changement et réévaluez la situation conformément aux instructions. Le rapport mentionnera l'escalier, l'heure, la présence d'eau, les plaintes et l'évolution, sans attribuer une faute ou un diagnostic. La correction du sol glissant constitue un sujet de prévention distinct de la prise en charge médicale."""),
    ['Situation', 'Point de vigilance'], [
        ['Malaise sans plaie visible', 'Ne pas banaliser ; faire décrire les signes et alerter.'],
        ['Brûlure thermique', 'Refroidir selon les consignes ; aucun produit improvisé.'],
        ['Électrisation', 'Danger électrique supprimé avant contact et évaluation médicale.'],
        ['Douleur après chute', 'Limiter les mouvements et ne pas tester la marche.']],
    ['Un malaise peut être urgent sans lésion visible.', 'Une brûlure électrique peut masquer des lésions internes.', 'Ne pas déplacer une victime pour la commodité du service.', 'Toute évolution de conscience ou de respiration doit être transmise.'],
    'La reprise de circulation attendra', 'Un salarié vient de chuter et le responsable veut rouvrir immédiatement l’escalier.', [
        question('Il se plaint du dos. Quelle décision privilégiez-vous ?', 'Protéger la zone et limiter les mouvements en attendant les secours.', 'Le faire marcher pour vérifier si la douleur est sérieuse.', 'Le porter au fauteuil le plus proche pour libérer le passage.', 'La commodité de circulation ne justifie pas un déplacement potentiellement aggravant.'),
        question('Il devient somnolent. Quelle information est prioritaire ?', 'L’évolution de son état au régulateur, avec une réévaluation.', 'La durée restante de votre vacation.', 'L’identité du fournisseur de nettoyage.', 'Une modification de conscience peut changer la prise en charge.'),
        question('Quelle formulation convient au compte rendu ?', 'Douleur au dos signalée après chute, puis baisse de réactivité observée.', 'Fracture de vertèbre certaine causée par une négligence.', 'Personne peu motivée pour se relever.', 'Une trace fiable distingue faits, plaintes et observations sans diagnostic ni jugement.')], [
        question('Une personne décrit une douleur thoracique soudaine. Que faites-vous ?', 'Alerter rapidement et suivre les consignes médicales.', 'Lui proposer de finir sa tâche avant de consulter.', 'Conclure à une crise d’angoisse sans autre vérification.', 'Une douleur thoracique brutale doit être considérée comme potentiellement urgente.'),
        question('Quel geste est à éviter sur une brûlure ?', 'Appliquer de la glace ou un corps gras improvisé.', 'Supprimer le danger avant d’approcher.', 'Demander un avis médical en cas de doute.', 'Les produits improvisés ou la glace peuvent aggraver la lésion.'),
        question('Quelle donnée remplace utilement un diagnostic supposé ?', 'Le mécanisme connu et les signes observés.', 'Une rumeur recueillie dans le groupe de collègues.', 'L’avis d’un témoin sur la personnalité de la victime.', 'Les secours ont besoin de faits et de signes pour évaluer la victime.')])


add('02', 1, 'Libertés, égalité, fraternité et dignité dans la mission',
    'Traduire les principes républicains en décisions d’accueil et de sécurité respectueuses des personnes.',
    'revision_theorique', ['https://www.elysee.fr/la-presidence/les-principes-de-la-republique', 'https://www.defenseurdesdroits.fr/foire-aux-questions-faq-184'], [
    sec('Des principes qui encadrent vos décisions', """Les principes de la République ne constituent pas un chapitre séparé du travail de terrain. Ils orientent la manière d'accueillir, de contrôler, d'expliquer une limite et de rendre compte. La liberté protège notamment l'expression, les convictions et les déplacements dans les conditions prévues par la loi. L'égalité demande de traiter de façon cohérente les situations comparables. La fraternité invite à une relation respectueuse et à l'assistance aux personnes en difficulté. Ces principes n'interdisent pas toute règle d'accès ; ils obligent à vérifier son fondement et la manière de l'appliquer.

La dignité reste due à chacun, y compris à une personne agressive ou soupçonnée d'une infraction. Une intervention ne doit pas chercher à humilier, à exposer au public ou à obtenir une soumission symbolique. Vous pouvez poser une limite ferme en conservant le vouvoiement, une explication courte et un espace de dialogue. Le métier ne donne pas le pouvoir de « donner une leçon ». L'autorité professionnelle se reconnaît à la maîtrise de l'action et à sa justification, pas au volume de voix ou aux propos dévalorisants."""),
    sec('Repérer une discrimination dans une consigne', """Une discrimination combine, dans les situations visées par la loi, un traitement défavorable avec un critère interdit tel que l'origine, le sexe, le handicap ou les convictions. La vigilance doit porter aussi sur les règles apparemment neutres qui excluent sans justification adaptée certaines personnes. Un agent ne doit pas sélectionner ses contrôles à partir de l'apparence, d'un accent ou d'une religion supposée. La règle doit s'appuyer sur la situation et sur le cadre du site : validité d'un titre, accès autorisé, comportement objectivement constaté ou risque identifié.

Lorsque le client demande un traitement discriminatoire, la présence d'une consigne écrite ne la rend pas licite. Reformulez le besoin de sécurité et demandez une règle objective. Par exemple, contrôler un titre d'accès pour tous les visiteurs d'une zone restreinte répond au besoin de vérifier l'autorisation ; exclure une catégorie de personnes en raison de leur origine n'y répond pas. En cas de pression, saisissez la hiérarchie et conservez une trace factuelle de la demande. Ne transformez pas le désaccord avec le client en débat public devant les visiteurs."""),
    sec('Égalité ne signifie pas rigidité identique', """Une personne malentendante peut avoir besoin que vous écriviez une instruction courte ; une personne à mobilité réduite peut emprunter un accès adapté. Ces aménagements permettent d'atteindre le même objectif de sécurité sans imposer à tous un parcours matériel identique. Demandez ce qui faciliterait l'échange et adressez-vous directement à la personne, même lorsqu'elle est accompagnée. Ne confondez pas difficulté de compréhension, handicap, émotion et mauvaise volonté. Un refus de contact physique ou un regard fuyant ne permet pas à lui seul d'attribuer une intention malveillante.

Avant de décider, utilisez trois questions : quel fait justifie mon action, quelle règle s'applique et quelle solution respecte la personne tout en protégeant le site ? Cette méthode rend votre décision explicable à un collègue, à la hiérarchie et à la personne contrôlée. Après l'incident, la trace doit rester centrée sur le motif objectif. Une formule telle que « titre d'accès absent, responsable appelé à 10 h 15 » est vérifiable. Une qualification globale sur une population ou une personnalité ne l'est pas et peut encourager de futures décisions injustifiées."""),
    ], example('Même règle, accès adapté', """À l'entrée d'un salon professionnel, tous les visiteurs doivent présenter une inscription. Une personne utilise un fauteuil et l'étroitesse de la file empêche son passage. Vous gardez la même exigence de contrôle du titre, mais organisez le passage par l'accès adapté avec le collègue concerné. Vous expliquez le trajet directement à la personne, sans lui imposer une aide qu'elle n'a pas demandée.

Un autre visiteur proteste contre un « privilège ». Vous indiquez simplement que le contrôle reste identique et que le chemin est adapté à l'accessibilité. Cette réponse protège l'objectif de sécurité et la dignité de chacun. Elle ne nécessite ni de révéler des informations de santé ni de commenter le handicap devant la file."""),
    ['Principe', 'Traduction professionnelle'], [
        ['Liberté', 'Ne limiter l’accès ou l’action que dans le cadre applicable.'],
        ['Égalité', 'Appliquer une règle objective aux situations comparables.'],
        ['Fraternité', 'Aider et orienter les personnes en difficulté.'],
        ['Dignité', 'Intervenir sans humiliation ni exposition inutile.']],
    ['Une consigne discriminatoire ne devient pas licite parce qu’elle est écrite.', 'Les faits justifient un contrôle, pas les stéréotypes.', 'Une adaptation d’accès peut assurer l’égalité.', 'Le respect reste dû même pendant un conflit.'],
    'Une consigne d’accueil contestable', 'Le responsable demande de contrôler davantage les personnes ayant un accent étranger.', [
        question('Quelle analyse faites-vous de cette demande ?', 'Elle repose sur un critère sans lien objectif avec le droit d’accès.', 'Elle devient acceptable si le client la confirme par courriel.', 'Elle est justifiée par le seul fait que la file est longue.', 'L’accent ne permet pas de déterminer une autorisation d’accès ou une menace.'),
        question('Quelle alternative proposez-vous ?', 'Vérifier les titres selon une règle commune ou un critère objectif de contrôle.', 'Demander leur nationalité à tous ceux qui vous paraissent différents.', 'Laisser votre collègue appliquer la consigne pour ne pas être impliqué.', 'Une règle fondée sur l’autorisation d’accès répond au besoin sans discrimination.'),
        question('La pression persiste. Quelle suite convient ?', 'Alerter la hiérarchie et tracer factuellement la demande et votre réponse.', 'Humilier publiquement le client pour faire cesser la discussion.', 'Appliquer la consigne puis supprimer toute trace.', 'Le relais hiérarchique et la trace permettent un traitement professionnel du problème.')], [
        question('Quel motif peut objectivement justifier une vérification d’accès ?', 'L’absence d’un titre exigé pour la zone concernée.', 'Un accent que l’agent trouve inhabituel.', 'Une conviction religieuse supposée.', 'Le titre d’accès correspond directement à la règle du site.'),
        question('Adapter le passage à une personne en fauteuil signifie-t-il supprimer le contrôle ?', 'Non, le contrôle peut rester identique avec un chemin adapté.', 'Oui, toute adaptation interdit de vérifier son titre.', 'Oui, l’égalité impose nécessairement une absence de contrôle.', 'L’accessibilité du parcours et l’autorisation d’accès sont deux questions distinctes.'),
        question('La dignité doit-elle être respectée pour une personne agressive ?', 'Oui, tout en prenant les mesures de protection adaptées.', 'Non, dès qu’une insulte a été prononcée.', 'Uniquement lorsque la personne présente des excuses.', 'Le comportement de la personne ne supprime pas ses droits.')])

add('02', 2, 'Laïcité, liberté de conscience et neutralité',
    'Distinguer convictions personnelles, règles de neutralité applicables et exigences objectives de la mission.',
    'revision_theorique', ['https://www.service-public.gouv.fr/particuliers/vosdroits/F20367', 'https://www.laicite.gouv.fr/documentation/ressources/depliant-comprendre-laicite.html', 'https://formation-civique.interieur.gouv.fr/fiches-par-thematiques/principes-et-valeurs-de-la-republique/laicite/la-laicite-au-travail/'], [
    sec('Distinguer la personne, l’employeur et le service', """La liberté de conscience protège la possibilité d'avoir une conviction, d'en changer ou de n'en avoir aucune. La laïcité organise notamment la neutralité de l'État et l'égalité devant le service public. Elle ne signifie pas que toute expression d'une conviction est interdite partout. Pour l'agent privé, la première question est le cadre de la mission : entreprise privée ordinaire, participation à l'exécution d'un service public, règlement intérieur, exigences de sécurité et obligations propres à la tenue. On ne déduit pas une règle juridique du seul nom du bâtiment.

Dans une entreprise privée, les restrictions aux libertés doivent reposer sur un cadre valable et être justifiées et proportionnées. Un règlement intérieur peut prévoir certaines obligations dans les conditions du droit du travail ; une activité participant à un service public peut imposer la neutralité aux personnes qui y concourent. L'agent ne tranche pas seul une difficulté nouvelle entre ces régimes. Il vérifie la consigne validée auprès de sa hiérarchie. La règle appliquée doit être expliquée par sa fonction, sans jugement sur la valeur d'une religion ou d'une conviction."""),
    sec('Rester impartial dans la relation avec le public', """Quelle que soit la mission, le contrôle d'accès ne doit pas devenir une discussion sur les croyances. Vous recherchez les mêmes éléments utiles : autorisation, comportement, objet éventuellement interdit, règle propre au site. Un usager exprimant une conviction ne dispose pas automatiquement d'un droit à contourner une mesure de sécurité ; l'agent ne peut pas davantage inventer une interdiction générale. S'il existe une demande d'aménagement, faites préciser son objet et recherchez une réponse compatible avec le cadre. Une solution discrète peut prévenir le conflit sans diminuer le contrôle.

La neutralité professionnelle se manifeste aussi par les paroles : ne pas convertir, dénigrer, commenter les pratiques d'un visiteur ou attribuer un incident à un groupe. Une personne peut refuser d'expliquer sa vie privée. Les échanges doivent rester limités à ce qui est nécessaire. Si un tiers essaie de vous entraîner dans une polémique, recentrez la discussion sur la règle : « Mon rôle est de vérifier l'accès à cette zone ; je peux vous expliquer la procédure ». Cette phrase maintient votre rôle sans exprimer une préférence personnelle."""),
    sec('Appliquer une restriction avec méthode', """Un équipement de protection, une identification nécessaire ou une exigence légale peut imposer des adaptations à une tenue ou à un comportement. Vérifiez d'abord la règle et le besoin précis, puis les modalités possibles : espace permettant une vérification discrète, recours au responsable compétent, explication accessible ou solution technique autorisée. N'ajoutez pas une condition inutile. Le consentement demandé pour certains contrôles corporels et les règles de même sexe demeurent applicables ; une formule générale sur la laïcité ne permet pas de les contourner.

Lorsqu'une difficulté ne peut pas être réglée immédiatement, annoncez ce que vous faites et qui prend la décision. Gardez un ton neutre et évitez la discussion devant une file. La trace professionnelle mentionne la demande concrète et le relais sollicité, avec le minimum d'informations personnelles. Elle ne doit pas devenir un fichier de convictions des usagers. Au débriefing, l'équipe vérifie si la consigne était suffisamment claire, si une adaptation était disponible et si tous les agents donnaient la même explication. Une règle comprise et cohérente réduit les tensions à la prochaine prise de poste."""),
    ], example('Une vérification d’identité à l’accueil', """Dans un établissement où un contrôle nominatif est prévu, une visiteuse demande une vérification à l'écart de la file. Vous ne lui demandez pas de justifier ses convictions. Vous vérifiez que la procédure du site permet cet aménagement et appelez la personne compétente pour effectuer le contrôle dans les conditions adaptées.

Pendant l'attente, un collègue affirme que « la laïcité interdit toutes les tenues religieuses ». Vous recentrez l'échange : il faut appliquer le cadre précis de la mission et la vérification d'accès, sans inventer une règle générale. La décision ne dépend ni de votre conviction ni de celle du collègue. Le compte rendu indique uniquement la modalité d'accueil et le résultat utile du contrôle."""),
    ['Question à poser', 'Intérêt pour la décision'], [
        ['Quel régime s’applique à la mission ?', 'Distinguer entreprise privée et participation au service public.'],
        ['Quel besoin justifie la restriction ?', 'Identifier sécurité, identification ou obligation prévue.'],
        ['Existe-t-il une adaptation autorisée ?', 'Atteindre l’objectif avec une atteinte limitée aux libertés.'],
        ['Qui valide en cas de doute ?', 'Éviter d’improviser une règle personnelle.']],
    ['La laïcité ne signifie pas une interdiction générale des convictions.', 'Une mission privée peut relever de règles différentes selon son cadre.', 'Les restrictions doivent avoir une justification valable.', 'L’agent applique la règle sans débat sur les croyances.'],
    'Une demande de contrôle discret', 'Une visiteuse accepte la vérification exigée mais demande qu’elle se fasse à l’écart.', [
        question('Quel est votre premier raisonnement ?', 'Vérifier une modalité adaptée dans le cadre de la procédure.', 'Déduire de sa demande une intention de fraude.', 'Lui demander de défendre publiquement ses convictions.', 'Une demande d’aménagement n’est pas une preuve de fraude.'),
        question('Un collègue invoque une interdiction générale de toute religion. Que faites-vous ?', 'Revenir au cadre réel de la mission et solliciter la règle validée.', 'Appliquer sa formule parce qu’il a plus d’ancienneté.', 'Demander aux visiteurs de voter sur la règle.', 'L’ancienneté ou l’opinion ne remplace pas le cadre juridique applicable.'),
        question('Que faut-il consigner si un relais est nécessaire ?', 'La demande concrète, la personne sollicitée et la suite utile.', 'Une liste des croyances supposées de la visiteuse.', 'Les commentaires des autres clients sur sa tenue.', 'La trace doit servir la mission avec le minimum d’informations personnelles.')], [
        question('La liberté de conscience protège notamment quoi ?', 'Le choix d’avoir une conviction ou de n’en avoir aucune.', 'Le droit de contourner toute règle de sécurité.', 'Le droit pour un agent d’imposer sa conviction au public.', 'Elle protège la personne sans supprimer le cadre légal des activités.'),
        question('Dans le secteur privé, une restriction aux libertés doit être quoi ?', 'Justifiée dans un cadre valable et proportionnée.', 'Fondée uniquement sur le souhait oral d’un visiteur.', 'Identique à toutes les règles de la fonction publique par défaut.', 'Les régimes doivent être distingués et les restrictions légalement justifiées.'),
        question('Quel échange convient au poste ?', 'Expliquer la procédure utile sans commenter les croyances.', 'Chercher à convaincre la personne de changer de conviction.', 'Débattre devant la file de la valeur de sa religion.', 'Le dialogue professionnel reste centré sur la mission.')])

add('02', 3, 'Symboles républicains, État de droit et ordre public',
    'Reconnaître les symboles officiels et situer la sécurité privée dans un État de droit.',
    'revision_theorique', ['https://www.elysee.fr/la-presidence/les-symboles-de-la-republique-francaise', 'https://www.legifrance.gouv.fr/loda/article_lc/LEGIARTI000006527453/', 'https://www.defenseurdesdroits.fr/controler-le-respect-de-la-deontologie-par-les-professionnels-de-la-securite-195'], [
    sec('Connaître les symboles et leur portée', """L'emblème national est le drapeau tricolore bleu, blanc et rouge. La Marseillaise est l'hymne national et « Liberté, Égalité, Fraternité » la devise de la République. Ces éléments figurent dans la Constitution et représentent la communauté politique au-delà des opinions individuelles. Marianne incarne également la République dans de nombreux lieux publics. Pour un agent, les connaître permet de comprendre une cérémonie, de reconnaître les repères institutionnels et d'adopter une attitude respectueuse dans un bâtiment ou lors d'un événement officiel.

Le respect dû à ces symboles ne vous attribue pas un pouvoir de sanction. Un comportement que vous jugez déplacé doit être analysé à partir de faits et des règles applicables. La liberté d'expression conserve sa place ; les éventuelles infractions relèvent des autorités compétentes. Préservez les personnes, signalez un fait préoccupant et sollicitez le relais prévu sans transformer une opinion personnelle en ordre contraignant. Il faut distinguer désaccord, perturbation du fonctionnement, dégradation matérielle et violence : ces situations n'appellent pas automatiquement la même réponse."""),
    sec('L’État de droit limite aussi ceux qui protègent', """Dans un État de droit, chacun est soumis à la loi, y compris les autorités et les professionnels de la sécurité. Les décisions peuvent être contrôlées et les personnes disposent de recours. La séparation des pouvoirs et l'indépendance de la justice évitent que celui qui observe un fait soit aussi celui qui décide seul de la culpabilité et de la sanction. L'agent privé contribue à la prévention et à la protection dans un cadre défini ; il ne remplace ni le juge ni un service de police.

Une consigne du client doit donc être compatible avec les normes qui lui sont supérieures. La possession d'un lieu ne donne pas tous les pouvoirs sur les personnes qui s'y trouvent. Un règlement peut organiser des accès, mais ne peut autoriser arbitrairement une fouille forcée, une humiliation ou une rétention sans fondement. Lorsque vous recevez une instruction inhabituelle, recherchez le besoin concret, vérifiez les limites et demandez une validation. Cette démarche protège à la fois les personnes, l'entreprise et votre responsabilité professionnelle."""),
    sec('Prévenir les troubles sans confondre les fonctions', """L'ordre public recouvre notamment des exigences de sécurité et de tranquillité. Votre contribution consiste à prévenir les incidents dans la mission confiée, à alerter, à appliquer les consignes licites et à faciliter les interventions compétentes. Elle ne constitue pas un pouvoir général de contrôle dans l'espace public. La tenue, les insignes et la manière de vous présenter doivent permettre de vous identifier comme agent de sécurité privée. Une phrase comme « vous êtes obligé parce que je représente la police » crée une confusion incompatible avec votre fonction.

En cas de contestation, donnez un interlocuteur et une procédure de recours lorsque ceux-ci sont prévus. Accepter qu'une personne demande une explication ne signifie pas perdre la maîtrise de la situation. Une décision professionnelle doit pouvoir être relue : motif, règle, action, limites, transmission. Si un incident devient dangereux, la protection et l'appel aux forces de l'ordre prennent la priorité. L'analyse juridique détaillée et le traitement d'une réclamation se poursuivront ensuite dans le cadre approprié, sans organiser un procès improvisé au poste de garde."""),
    ], example('Une cérémonie dans un équipement public', """Vous assurez le contrôle d'accès lors d'une cérémonie. Un participant exprime une opinion critique tandis qu'un autre dégrade un élément de signalétique. Le premier échange peut nécessiter une régulation si le fonctionnement est perturbé, mais le contenu d'une opinion ne suffit pas à lui seul à justifier une intervention coercitive. La dégradation constitue un fait matériel distinct à signaler.

Vous appliquez les consignes de protection, appelez le responsable et les forces de l'ordre si nécessaire, puis décrivez séparément les deux faits. Votre présentation reste celle d'un agent privé. Vous ne menacez pas d'une peine et n'exigez pas d'excuses publiques : la mission porte sur la sécurité, les décisions judiciaires appartiennent aux autorités compétentes."""),
    ['Repère', 'À retenir pour la mission'], [
        ['Drapeau tricolore', 'Emblème national bleu, blanc, rouge.'],
        ['Marseillaise', 'Hymne national.'],
        ['État de droit', 'Les actions de sécurité restent soumises aux règles et au contrôle.'],
        ['Sécurité privée', 'Une contribution encadrée, distincte des pouvoirs de police.']],
    ['Connaître les symboles aide à respecter le cadre institutionnel.', 'Le client et l’agent restent soumis à la loi.', 'Observer un fait ne donne pas le pouvoir de juger et punir.', 'Une décision doit être explicable et contrôlable.'],
    'Une demande excessive du client', 'Après une contestation, le client exige que vous enfermiez la personne jusqu’à ses excuses.', [
        question('Quel problème identifiez-vous ?', 'Une mesure privative de liberté sans fondement présenté.', 'Une consigne toujours valable parce que le lieu est privé.', 'Une formalité normale de gestion de réclamation.', 'Le droit de propriété ne donne pas un pouvoir général de rétention.'),
        question('Quelle réponse opérationnelle convient ?', 'Refuser cette mesure, protéger et solliciter le relais approprié.', 'Appliquer l’ordre puis demander une validation après.', 'Menacer la personne d’une condamnation immédiate.', 'La sécurité se maintient dans le cadre légal, sans sanction improvisée.'),
        question('Comment rendez-vous compte ?', 'Par les propos exacts utiles, les faits et les actions réalisées.', 'Par une conclusion sur la culpabilité définitive du visiteur.', 'Par des commentaires sur ses opinions politiques supposées.', 'Une trace factuelle permet le contrôle de l’intervention.')], [
        question('Quel est l’hymne national français ?', 'La Marseillaise.', 'Le Chant des partisans.', 'L’Hymne à la joie.', 'La Constitution désigne La Marseillaise comme hymne national.'),
        question('Qui est soumis à la loi dans un État de droit ?', 'Les personnes, les institutions et les professionnels de la sécurité.', 'Uniquement les personnes qui ne possèdent pas le site.', 'Les agents privés seulement pendant leur formation.', 'Le cadre légal s’impose également à ceux qui exercent une mission de protection.'),
        question('Quelle présentation est adaptée ?', 'Agent de sécurité privée du site.', 'Policier du client.', 'Autorité judiciaire de l’établissement.', 'La fonction doit être clairement distinguée des services publics de sécurité.')])


add('03', 1, 'Actualiser son cadre d’exercice et ses autorisations',
    'Vérifier les conditions d’exercice, les limites de la mission, l’identification professionnelle et le cadre de l’armement.',
    'revision_theorique', [DEONTO, 'https://www.cnaps.interieur.gouv.fr/Demarches-en-ligne/Vous-etes-un-particulier/Renouveler-votre-carte-professionnelle2/Renouveler-votre-carte-professionnelle'], [
    sec('L’expérience ne remplace pas la validité du titre', """Le MAC sert à mettre à jour une pratique déjà exercée. Il ne suffit donc pas de se souvenir de ce qui était vrai lors de la formation initiale. Avant une mission, l'agent et l'employeur doivent s'assurer que l'activité confiée correspond au titre détenu, à sa validité et aux conditions d'exercice. La carte professionnelle du CNAPS, les autorisations de l'entreprise et les documents d'identification fournis par l'employeur ont des fonctions différentes. Un badge du client ne crée pas un droit d'exercer et une ancienne expérience ne rétablit pas une carte expirée.

Le renouvellement s'anticipe. Le stage réglementaire MAC se situe dans la période prévue par l'arrêté et s'accompagne des justificatifs requis pour la démarche CNAPS. La consultation d'un cours ou la réussite d'un examen blanc ne vaut pas attestation de stage. L'évaluation pédagogique préalable réglementaire comporte dix questions à réponse courte et relève de l'organisation du formateur ; le diagnostic par QCM du site est un outil distinct. Les éventuelles dispenses de module doivent être demandées et justifiées, puis contrôlées par l'organisme, sans conversion automatique du temps passé en ligne."""),
    sec('Accepter une mission dans le périmètre autorisé', """Le livre VI du code de la sécurité intérieure organise les activités privées de sécurité. Le principe d'exercice exclusif et les incompatibilités imposent de vérifier la nature des prestations proposées. Pour l'agent, le réflexe pratique consiste à repérer lorsqu'une demande sort du périmètre prévu : mission de police, investigation personnelle, tâche incompatible avec la surveillance ou extension d'une activité nécessitant une qualification spécifique. Une demande du client n'élargit pas vos prérogatives. La réponse doit passer par votre hiérarchie et une consigne licite clairement définie.

Votre lieu d'intervention compte également. La surveillance s'exerce dans le cadre des biens et lieux confiés, avec les éventuelles dispositions particulières prévues par les textes. Ne transformez pas une ronde de site en patrouille générale de contrôle des passants. La prévention, la présence dissuasive et le signalement restent possibles dans leurs limites, mais une extension de mission doit être vérifiée. Lorsque vous changez de poste ou d'événement, relisez les consignes : une habilitation ou une autorisation valable sur un dispositif ne doit pas être supposée valable partout."""),
    sec('Tenue, identification et armes : aucune improvisation', """La tenue et les insignes doivent permettre de reconnaître la sécurité privée sans confusion avec la police, la gendarmerie ou un autre service public. Vérifiez les éléments réglementaires d'identification et ceux de l'entreprise, leur lisibilité et leur présence selon le régime applicable à votre activité. Un ancien uniforme conservé par habitude ou un accessoire ressemblant à un insigne officiel peut poser problème. La manière de se présenter fait partie du même contrôle : expliquez votre fonction exacte, sans vous attribuer une autorité que vous ne possédez pas.

La détention d'une arme à titre personnel, même licite, n'autorise pas son port pendant une mission de sécurité privée. L'armement professionnel relève d'un régime spécifique comportant des conditions d'autorisation, de qualification, de conservation, de transport et d'emploi. Ce parcours MAC APS ordinaire n'est pas une formation de surveillance armée. N'apportez pas un moyen personnel pour compenser un sentiment d'insécurité ; signalez le risque et demandez une organisation adaptée. Le cadre de la légitime défense ne constitue jamais une permission générale de porter une arme. La prévention du risque commence par la conformité de la mission et des moyens."""),
    ], example('Un remplacement demandé au dernier moment', """On vous propose de remplacer un collègue sur un événement que vous connaissez. Le client ajoute une mission de palpation systématique et vous invite à prendre « votre matériel personnel si cela vous rassure ». Vous vérifiez votre titre, la consigne, le dispositif juridique et les moyens autorisés avant d'accepter cette extension.

Votre réponse professionnelle précise que l'ancienneté sur le site ne dispense pas de vérifier le cadre du jour. Vous demandez à votre responsable les conditions applicables et les effectifs adaptés. Cette vérification évite d'apprendre au début de la vacation qu'un contrôle ou un équipement n'est pas autorisé. Le besoin de sécurité doit être traduit en organisation conforme, sans initiative d'armement personnelle."""),
    ['Document ou élément', 'Question de contrôle'], [
        ['Titre professionnel', 'Activité correspondante et validité vérifiées ?'],
        ['Consigne du poste', 'Périmètre, limites et relais identifiés ?'],
        ['Tenue', 'Identification conforme et absence de confusion publique ?'],
        ['Moyens de mission', 'Équipements autorisés dans le cadre applicable ?']],
    ['Une expérience antérieure ne remplace pas un titre valide.', 'Un badge de site n’est pas une carte CNAPS.', 'Une extension de mission exige une vérification.', 'Le port d’une arme ne découle pas d’une détention personnelle.'],
    'Une mission élargie sans préparation', 'À la relève, le client annonce de nouveaux contrôles sans document disponible.', [
        question('Que vérifiez-vous avant de les réaliser ?', 'Le cadre applicable, la consigne validée et les conditions individuelles.', 'Seulement si un collègue l’a déjà fait ailleurs.', 'La satisfaction du client indépendamment des textes.', 'Une pratique antérieure ne prouve pas que les conditions sont réunies sur ce dispositif.'),
        question('Le client propose d’utiliser une arme personnelle. Quelle réponse convient ?', 'Ne pas l’apporter et demander une organisation conforme au risque.', 'Accepter si vous la détenez légalement à votre domicile.', 'La dissimuler pour qu’elle ne change pas la présentation du poste.', 'Détention personnelle et armement professionnel obéissent à des cadres distincts.'),
        question('Quelle trace est utile à la relève ?', 'La demande reçue, la vérification sollicitée et la consigne finalement validée.', 'Une mention « comme d’habitude » sans détail.', 'Le numéro privé de tous les visiteurs attendus.', 'La trace doit expliquer la décision opérationnelle prise.')], [
        question('Quel élément donne à lui seul le droit d’exercer une activité privée de sécurité ?', 'Aucun badge du client ne remplace les conditions légales et le titre requis.', 'Le badge d’accès au site.', 'La lettre de recommandation d’un ancien employeur.', 'L’accès matériel au site et le droit professionnel d’exercer sont distincts.'),
        question('Le QCM du parcours remplace-t-il l’évaluation initiale réglementaire ?', 'Non, le formateur organise distinctement les dix réponses courtes.', 'Oui, s’il contient dix questions.', 'Oui, dès que le score dépasse 80 %.', 'Le format réglementaire préalable et le diagnostic d’entraînement ne doivent pas être confondus.'),
        question('Que doit éviter la tenue de l’agent ?', 'La confusion avec un service public de sécurité.', 'Toute identification de l’entreprise.', 'Toute indication de sécurité privée.', 'La fonction privée doit être identifiable et distincte de l’autorité publique.')])

add('03', 2, 'Déontologie, confidentialité et vie privée',
    'Adopter une conduite professionnelle et limiter l’usage des informations personnelles à la mission autorisée.',
    'revision_theorique', [DEONTO, 'https://www.cnil.fr/fr/la-videosurveillance-dans-les-commerces', 'https://www.cnil.fr/fr/la-videosurveillance-videoprotection-au-travail'], [
    sec('La déontologie se vérifie dans les petites décisions', """Respect des lois, dignité, probité, maîtrise de soi et confidentialité doivent guider l'ensemble de la vacation. Ils se traduisent dans des choix simples : refuser un avantage destiné à contourner un contrôle, rester sobre, ne pas provoquer un conflit et rendre compte d'une erreur. L'agent ne doit pas profiter de l'accès à des lieux ou à des informations pour un intérêt personnel. La confiance du client dépend autant de ces décisions quotidiennes que de la réaction face à un incident spectaculaire.

Un comportement professionnel reste nécessaire lorsque personne ne semble regarder. La fatigue, la routine ou l'habitude de côtoyer les salariés du site peuvent réduire la vigilance. Ne laissez pas un proche entrer sur la seule base de votre relation ; ne prêtez pas un identifiant et ne demandez pas à un collègue de confirmer un contrôle qu'il n'a pas réalisé. Une erreur doit être remontée assez tôt pour permettre une correction. La dissimuler dégrade la traçabilité et peut créer un risque supplémentaire lors de la prochaine relève."""),
    sec('Distinguer information utile et curiosité', """Le poste de sécurité donne parfois accès à des images, des noms, des horaires, des plaques d'immatriculation et des informations de santé. Cet accès répond à une finalité et à des habilitations. Il ne permet pas de consulter un dossier pour savoir ce que fait une connaissance, de suivre un salarié par curiosité ou d'utiliser une caméra à une autre fin que celle prévue. Les images doivent être consultées par les personnes autorisées, dans le cadre du dispositif. Un collègue sympathique mais non habilité n'est pas un destinataire légitime.

Le compte rendu doit contenir les données nécessaires à l'incident et à son traitement, sans accumuler des informations sans rapport. Une plainte spontanée de la victime peut être rapportée aux secours ; son histoire médicale complète ne doit pas circuler dans la main courante accessible à tous. Ne photographiez pas un écran avec votre téléphone et ne diffusez pas un extrait vidéo dans une messagerie personnelle. L'extraction ou la communication d'images suit la procédure validée, notamment lorsqu'une autorité compétente en fait la demande. Préservez la trace de cette opération dans le dispositif prévu."""),
    sec('Un secret n’interdit pas un signalement nécessaire', """La confidentialité protège l'information contre une diffusion injustifiée ; elle ne justifie pas de cacher un danger aux interlocuteurs compétents. Il faut distinguer raconter un incident à des tiers et transmettre les éléments nécessaires aux secours, à la hiérarchie ou aux autorités dans le cadre légal. En cas de demande inhabituelle, vérifiez l'identité du demandeur, son habilitation, l'objet et le canal de transmission. Ne confirmez pas à un inconnu qu'une personne travaille ou séjourne sur le site simplement parce qu'il connaît son nom.

La vie privée et le droit de propriété concernent aussi les contrôles matériels. Un objet vu dans un sac ne devient pas une information à commenter devant la file. Vous ne pouvez pas retenir un téléphone pour lire ses messages, parcourir des documents privés ou exiger le code d'un appareil au nom d'un contrôle d'accès ordinaire. Lorsque la mission vous confronte à une information sensible, concentrez-vous sur l'objectif autorisé et sollicitez le relais prévu. Une bonne transmission donne ce qui est nécessaire à la décision sans exposer inutilement la personne."""),
    ], example('Une demande de vidéo par messagerie', """Un responsable vous demande d'envoyer sur son téléphone personnel l'image d'un salarié entrant dans une réserve. Vous savez qu'il travaille sur le site, mais vous ne connaissez pas son habilitation au dispositif ni le motif exact. Vous lui indiquez que la demande doit suivre le canal autorisé et la personne responsable des images.

Vous ne prenez pas de photo de l'écran « en attendant ». Si un incident de sécurité justifie une conservation, vous demandez la préservation de la séquence selon la procédure. Vous tracez la demande utile, sans la présenter comme une infraction avérée du salarié filmé. Vous protégez ainsi la preuve possible et la vie privée, tout en permettant l'examen légitime de l'incident."""),
    ['Situation', 'Réponse professionnelle'], [
        ['Demande d’image par un tiers', 'Vérifier identité, habilitation, finalité et canal.'],
        ['Information de santé', 'Limiter la diffusion aux destinataires nécessaires.'],
        ['Téléphone d’un visiteur', 'Aucun accès au contenu au titre d’un contrôle ordinaire.'],
        ['Erreur ou accès indu', 'Signaler rapidement selon la procédure.']],
    ['L’habilitation ne se déduit pas d’une relation personnelle.', 'Les informations du poste servent la mission.', 'Aucune image sur une messagerie personnelle.', 'Confidentialité et signalement aux destinataires compétents sont compatibles.'],
    'Le message d’un ancien collègue', 'Un ancien collègue demande si son ex-partenaire est entrée sur le site et sollicite une capture.', [
        question('Que répondez-vous ?', 'Ne pas confirmer la présence ni transmettre l’image.', 'Répondre parce qu’il connaît les lieux.', 'Envoyer une image floutée mais confirmer l’horaire.', 'Une relation personnelle ne crée aucun droit d’accès aux informations du site.'),
        question('La demande insiste et devient menaçante. Que faites-vous ?', 'Signaler la demande et le risque au responsable selon la procédure.', 'Effacer la conversation et ne rien dire.', 'Chercher l’adresse personnelle de l’ex-partenaire.', 'Le caractère préoccupant de la demande doit être remonté sans étendre la collecte de données.'),
        question('Comment conservez-vous la trace utile ?', 'Dans le canal professionnel prévu avec les seuls éléments nécessaires.', 'Dans un groupe privé pour recueillir les avis des collègues.', 'Sur un appareil personnel accessible à votre famille.', 'La conservation doit rester maîtrisée et liée au traitement du risque.')], [
        question('Peut-on visionner une caméra pour suivre une connaissance par curiosité ?', 'Non, l’usage doit respecter la finalité et les habilitations.', 'Oui, si aucune capture n’est conservée.', 'Oui, pendant une pause.', 'L’absence d’enregistrement personnel ne rend pas légitime un visionnage détourné.'),
        question('Quel canal convient à une extraction d’images ?', 'La procédure autorisée et traçable du dispositif.', 'La messagerie personnelle la plus rapide.', 'Le compte d’un collègue absent.', 'L’extraction doit rester contrôlée et attribuable.'),
        question('Quelle donnée convient à une main courante d’incident ?', 'Le fait utile, daté et limité à la mission.', 'L’histoire médicale complète de la victime.', 'Les opinions supposées de la personne.', 'La minimisation réduit l’exposition de la vie privée tout en conservant l’information utile.')])

add('03', 3, 'Légitime défense, nécessité et proportion',
    'Différencier protection immédiate, état de nécessité et réaction punitive afin de rester dans les limites légales.',
    'revision_theorique', ['https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000006417218', 'https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000006417220', 'https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000029656384'], [
    sec('La protection répond à une atteinte actuelle', """La légitime défense est un cadre précis, pas une qualité attachée à la fonction d'agent. Pour protéger une personne, l'article 122-5 du code pénal vise une atteinte injustifiée, une réaction dans le même temps, commandée par la nécessité de la défense et sans disproportion entre les moyens employés et la gravité de l'atteinte. Il faut donc examiner des faits concrets : quel danger existe maintenant, qui est exposé, quelle action permet de le faire cesser et à quel moment cesse-t-elle d'être nécessaire ? Une insulte seule ne justifie pas de frapper son auteur.

La défense des biens relève de conditions particulières, plus restrictives, et ne permet notamment pas un homicide volontaire. Ne traduisez pas la valeur d'un objet en droit de blesser son voleur. L'agent doit privilégier la protection des personnes, le retrait, l'alerte et les possibilités proportionnées à la situation. Une fois l'atteinte terminée, une action destinée à punir ou à se venger ne relève plus d'une défense immédiate. Rattraper quelqu'un pour lui rendre un coup illustre précisément la rupture avec l'objectif de protection."""),
    sec('L’état de nécessité répond à un danger', """L'article 122-7 concerne un danger actuel ou imminent menaçant une personne ou un bien et un acte nécessaire à la sauvegarde, sans disproportion entre les moyens employés et la gravité de la menace. Ce cadre peut concerner une urgence qui n'est pas une agression. Il n'autorise pas une initiative commode simplement parce qu'elle semble efficace. Il faut pouvoir expliquer le danger concret, la nécessité de l'action et l'absence de moyen adapté moins dommageable. L'appréciation juridique dépend des circonstances réelles, pas du titre donné après coup dans un rapport.

Pour l'agent, ces notions conduisent à raisonner avant et pendant l'action. Une porte, un obstacle, un appel de renfort ou une mise à distance peuvent réduire le danger sans confrontation. La proportion n'est pas une règle de symétrie mécanique : répondre par le même geste ne suffit pas à rendre l'action licite. Le nombre de personnes, leur état, la persistance de la menace et les possibilités de protection comptent. Ce parcours n'enseigne pas de technique de combat ; les mises en situation de protection se travaillent dans un cadre sécurisé avec le formateur."""),
    sec('Cesser, secourir et rendre compte', """La réévaluation est permanente. Dès que le danger cesse ou qu'un moyen moins contraignant suffit, l'action doit s'adapter. Une personne maîtrisée, éloignée ou qui abandonne son attaque ne reste pas un support pour poursuivre une réaction émotionnelle. Appelez les forces de l'ordre lorsque la situation le justifie, demandez les secours si une blessure est possible et respectez la dignité de toutes les personnes. Le code de déontologie interdit les violences hors du cadre légal et impose un comportement responsable face à une personne appréhendée.

Le compte rendu doit permettre de comprendre ce que vous avez réellement perçu : paroles menaçantes utiles, gestes, distance, personnes exposées, moyens de retrait, actions et changement de situation. Évitez la phrase unique « légitime défense » comme justification suffisante. Décrire la chronologie ne revient pas à fabriquer une défense juridique ; cela préserve les faits pour l'examen compétent. Signalez aussi vos incertitudes et les témoins connus. La formation MAC permet d'identifier les automatismes dangereux, notamment la poursuite sous l'effet de la colère, et de préparer des réponses de protection maîtrisées."""),
    ], example('Une menace qui s’arrête', """À l'entrée d'un parking, un automobiliste descend, menace un agent puis recule lorsque l'équipe met les autres usagers à distance et demande du renfort. Il regagne son véhicule sans continuer l'attaque. Votre collègue veut le poursuivre pour « terminer l'explication ». Vous l'invitez à rester au poste sécurisé et transmettez les faits aux services compétents.

Le point décisif est l'évolution du danger. Une réaction qui pouvait viser la protection pendant l'attaque ne peut se prolonger pour obtenir réparation morale. Vous vérifiez l'état des personnes, préservez les éléments utiles et décrivez la chronologie. Le retour d'expérience porte sur le déclenchement du renfort, l'espace disponible et la maîtrise des émotions de l'équipe."""),
    ['Notion', 'Question utile'], [
        ['Atteinte injustifiée', 'Quelle agression concrète menace une personne maintenant ?'],
        ['Nécessité', 'L’action est-elle indispensable à la protection ?'],
        ['Proportion', 'Les moyens restent-ils adaptés à la gravité du danger ?'],
        ['Fin du danger', 'À quel moment faut-il cesser ou réduire l’action ?']],
    ['La fonction d’agent ne crée pas une légitime défense permanente.', 'Une réponse punitive n’est pas une protection.', 'La proportion dépend des circonstances, pas d’un geste identique.', 'Le danger doit être réévalué pendant toute l’intervention.'],
    'La colère après l’incident', 'Un individu vient d’insulter l’équipe puis s’éloigne ; votre collègue veut le rattraper.', [
        question('Une insulte seule autorise-t-elle un coup ?', 'Non, elle ne justifie pas à elle seule une violence physique.', 'Oui, si elle vise l’uniforme.', 'Oui, lorsque le client a entendu.', 'La gravité d’une parole ne crée pas automatiquement les conditions de la défense physique.'),
        question('La personne s’éloigne et ne menace plus. Quelle priorité retenez-vous ?', 'Cesser l’escalade, protéger le poste et rendre compte.', 'Poursuivre pour obtenir des excuses.', 'Demander à un visiteur de la bloquer pour discuter.', 'La disparition de la menace impose de réévaluer l’action ; la vengeance n’est pas une défense.'),
        question('Quelle rédaction est utile ?', 'Les paroles et gestes constatés, leur chronologie et les actions de protection.', 'La seule formule « réaction légitime » sans faits.', 'Une version modifiée pour rendre l’équipe irréprochable.', 'La qualité des faits permet l’examen de la situation sans conclusion fabriquée.')], [
        question('Quand une action défensive doit-elle être réévaluée ?', 'Pendant l’action et dès que le danger évolue.', 'Uniquement après la rédaction du rapport.', 'Jamais si elle était justifiée au départ.', 'Une justification initiale ne couvre pas automatiquement la poursuite de l’action.'),
        question('L’état de nécessité repose notamment sur quoi ?', 'Un danger actuel ou imminent et un acte nécessaire et proportionné.', 'Le souhait de finir plus vite une mission.', 'L’accord oral d’un témoin.', 'La commodité ou un accord ne remplace pas les conditions légales.'),
        question('La défense des biens autorise-t-elle n’importe quel moyen ?', 'Non, elle obéit à des conditions particulières et restrictives.', 'Oui, si le bien appartient au client.', 'Oui, lorsque l’objet a une valeur importante.', 'La valeur du bien ne supprime pas la protection de l’intégrité des personnes.')])

add('03', 4, 'Flagrance, appréhension et obligation d’assistance',
    'Distinguer soupçon et flagrance, reconnaître les limites de l’article 73 et agir face à une personne en danger.',
    'revision_theorique', ['https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000029000766/2026-01-03', 'https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000029656384', 'https://juridique.defenseurdesdroits.fr/index.php?id=1455&lvl=notice_display'], [
    sec('Un soupçon n’est pas une flagrance', """L'article 53 du code de procédure pénale décrit notamment la situation d'un crime ou d'un délit qui se commet actuellement ou vient de se commettre, ainsi que certaines circonstances proches des faits prévues par le texte. L'agent doit distinguer ce qu'il a vu, ce qu'un témoin rapporte et ce qu'il suppose. Une alarme, un comportement inhabituel ou une dénonciation peut justifier une vérification ou une alerte ; cela ne dispense pas d'apprécier les conditions d'une mesure portant atteinte à la liberté. Le mot « suspect » ne constitue pas une base juridique suffisante.

L'article 73 permet à toute personne d'appréhender l'auteur d'un crime flagrant ou d'un délit flagrant puni d'emprisonnement pour le conduire devant l'officier de police judiciaire le plus proche. Il ne confère pas à l'agent un pouvoir général de police ou d'enquête. Sa mise en œuvre exige des faits et le respect des limites de nécessité et de proportion. Avant d'agir, prenez en compte la sécurité des personnes et les possibilités d'alerte. L'intervention ne doit pas créer un danger disproportionné pour un enjeu matériel."""),
    sec('Aucun interrogatoire ni sanction privée', """Une personne appréhendée reste titulaire de droits. Il faut prévenir les services compétents, faciliter leur intervention et assurer la protection de la personne. Vous ne pouvez pas utiliser une rétention pour obtenir un remboursement, une signature, un aveu ou des excuses. Le local de sécurité n'est pas un lieu de garde à vue et la main courante n'est pas un jugement. Une fouille coercitive ou l'exploration du téléphone ne découle pas automatiquement de l'article 73. Chaque acte demande son propre fondement.

Le code de déontologie impose de préserver l'intégrité et la dignité de la personne et de faire appel sans délai aux services compétents selon la situation. Si son état nécessite des soins, alertez également les secours. Évitez l'exposition au public, les propos humiliants et les photographies. La durée et les modalités doivent rester liées à la remise aux autorités, jamais à un objectif commercial. Si les conditions légales ne sont pas établies, ne compensez pas l'incertitude par une privation de liberté « le temps de voir ». Sollicitez l'avis opérationnel des forces de l'ordre."""),
    sec('Assister sans s’exposer inutilement', """Le droit pénal vise aussi l'abstention volontaire face à une personne en péril lorsqu'une assistance est possible sans risque pour soi ou pour les tiers, par une action personnelle ou en provoquant un secours. Il prévoit également, sous ses conditions, l'obligation d'empêcher par une action immédiate un crime ou un délit contre l'intégrité corporelle lorsqu'elle peut être réalisée sans risque. Ces notions rappellent qu'observer un danger ne se résume pas à enregistrer l'information. Alerter efficacement, protéger une zone et orienter les secours sont des actions utiles.

L'assistance doit rester adaptée à vos compétences. Vous n'avez pas à vous jeter dans une agression armée ni à entrer dans un local toxique pour prouver votre engagement. Vous devez en revanche utiliser les moyens sûrs disponibles : appel urgent, avertissement des personnes, fermeture d'un accès si elle n'enferme pas les victimes, accueil des intervenants. Le rapport décrit ce que vous pouviez percevoir et faire, les dangers persistants et les actions engagées. Ce raisonnement évite deux erreurs opposées : intervenir sans mesure et rester passif en invoquant trop vite une absence de pouvoir."""),
    ], example('Une alarme antivol à la sortie', """Un portique sonne au passage d'une cliente. Vous n'avez pas observé de vol et elle présente un ticket. Vous expliquez le motif du contrôle et proposez la vérification prévue, dans ses limites. Le signal sonore seul ne permet pas d'organiser une rétention pour obtenir un aveu.

Dans un autre incident, un agent a directement constaté des faits susceptibles de relever d'un délit flagrant puni d'emprisonnement. L'équipe apprécie les conditions légales, protège les personnes et contacte les forces de l'ordre. Même dans ce cas, elle n'exige pas de signature privée en échange de la liberté. La différence tient aux faits établis et à la finalité de remise aux autorités, non à l'assurance avec laquelle le client accuse."""),
    ['Situation', 'Limite à identifier'], [
        ['Alarme ou signalement seul', 'Vérifier et alerter ; ne pas déduire automatiquement la flagrance.'],
        ['Article 73', 'Crime ou délit flagrant puni d’emprisonnement, remise à l’OPJ.'],
        ['Personne appréhendée', 'Dignité, intégrité, appel compétent et soins nécessaires.'],
        ['Personne en péril', 'Assistance adaptée sans risque pour soi ou les tiers.']],
    ['Le soupçon n’attribue pas un pouvoir général de rétention.', 'L’article 73 vise la remise à l’autorité compétente.', 'Aucun aveu ou paiement ne doit être exigé contre la liberté.', 'Provoquer les secours peut être l’assistance adaptée.'],
    'Le client veut un aveu', 'Une personne est soupçonnée d’un vol ; le client exige une signature avant de la laisser partir.', [
        question('Quelle limite devez-vous poser ?', 'La privation de liberté ne peut servir à obtenir un aveu privé.', 'L’aveu est acceptable si le document tient sur une page.', 'Le client peut fixer librement la durée dans sa propriété.', 'La finalité commerciale ou disciplinaire ne remplace pas le cadre de l’article 73.'),
        question('La personne se plaint d’un malaise. Que faites-vous ?', 'Prendre sa plainte au sérieux et demander les secours adaptés.', 'Attendre sa signature avant tout soin.', 'La filmer pour démontrer qu’elle simule.', 'La protection de l’intégrité reste due, quelle que soit la suspicion.'),
        question('Quelle transmission préparez-vous ?', 'Les faits observés, les limites connues, les actions et l’état de la personne.', 'Une conclusion de culpabilité négociée avec le client.', 'Un récit supprimant la demande de signature.', 'Les autorités ont besoin d’un compte rendu fidèle, y compris des difficultés de l’intervention.')], [
        question('L’article 73 est-il un pouvoir général d’enquête de l’agent ?', 'Non, il encadre une appréhension dans des cas précis.', 'Oui, dans tout commerce.', 'Oui, si l’agent a plus de cinq ans d’expérience.', 'Il ne transforme pas un agent privé en enquêteur ou officier de police.'),
        question('Quelle action peut constituer une assistance adaptée ?', 'Appeler efficacement les secours depuis une position sûre.', 'Se mettre obligatoirement en danger.', 'Attendre qu’un autre témoin agisse sans vérifier.', 'L’assistance peut consister à provoquer un secours lorsque l’action directe serait dangereuse.'),
        question('Une personne appréhendée conserve-t-elle sa dignité et le droit aux soins nécessaires ?', 'Oui, ces exigences demeurent applicables.', 'Non, jusqu’à l’arrivée de la police.', 'Seulement si elle reconnaît les faits.', 'La suspicion ou l’appréhension ne supprime pas ces protections.')])

add('03', 5, 'Décider, transmettre et conserver des faits fiables',
    'Construire une décision traçable et transmettre un incident sans confusion entre observation, témoignage et hypothèse.',
    'revision_theorique', [DEONTO, 'https://www.cnil.fr/fr/la-videoprotection'], [
    sec('Faire apparaître le raisonnement utile', """Un bon compte rendu permet à une personne absente de comprendre l'incident et la réponse apportée. Il répond aux questions utiles : quand, où, qui dans la mesure nécessaire, quoi, quel risque, quelles actions et quelle suite ? Il ne doit pas ressembler à un commentaire général sur la vacation. Une chronologie courte, avec les changements importants, est plus utile qu'une accumulation d'adjectifs. L'agent expérimenté gagne à vérifier les formules devenues automatiques : « rien à signaler » ne convient pas si une anomalie a été corrigée sans être transmise.

Séparez trois niveaux d'information. L'observation directe est ce que vous avez vu ou entendu vous-même. Le témoignage est attribué à sa source. L'hypothèse reste explicitement incertaine. Par exemple : « à 18 h 42, la porte était ouverte ; le technicien indique être intervenu à 18 h 30 ; la cause de l'ouverture n'est pas établie ». Cette rédaction est plus fiable que « le technicien a laissé ouvert », si vous ne l'avez pas observé. L'incertitude correctement exprimée améliore la décision au lieu de l'affaiblir."""),
    sec('Choisir le bon canal et le bon moment', """Un événement urgent appelle une transmission immédiate par le canal prévu, puis une trace. Le rapport ne doit pas retarder la protection ou l'appel aux secours. Le message oral commence par la localisation et la nature du risque, puis la demande précise : renfort, mise à distance, ouverture d'un accès ou appel d'un service. Faites confirmer une information déterminante. Les codes radio, lorsqu'ils existent, doivent être connus de tous ; un message incompris peut donner une fausse impression de coordination.

La hiérarchie, le client, les forces de l'ordre et les secours n'ont pas nécessairement besoin des mêmes informations. Transmettez ce qui sert leur rôle sans masquer un élément utile. Un responsable de maintenance a besoin de connaître la porte défectueuse ; les secours ont besoin de l'état d'une victime ; une réclamation sur une donnée personnelle suit un interlocuteur identifié. Évitez de diffuser indistinctement tout le dossier. Si un interlocuteur extérieur se présente par téléphone, vérifiez son identité par un moyen connu avant de communiquer des éléments sensibles."""),
    sec('Préserver les éléments sans les altérer', """Un objet, une image ou un journal d'accès peut contribuer à comprendre un incident. Préservez la zone et signalez l'existence de ces éléments sans les manipuler inutilement. Une extraction vidéo suit les habilitations et la procédure ; une photographie personnelle d'écran n'est pas une méthode de conservation adaptée. N'effacez pas une entrée erronée pour faire disparaître la première version : utilisez le mécanisme de correction traçable prévu par l'outil. Ne complétez pas de mémoire une heure précise que vous ne connaissez pas ; indiquez qu'elle est approximative.

À la relève, distinguez les faits clos de ce qui reste à traiter. Qui a été prévenu ? Une porte est-elle encore neutralisée ? Un appel est-il attendu ? Une consigne provisoire a-t-elle une échéance ? Une action sans responsable désigné peut rester en suspens malgré un rapport détaillé. Le retour d'expérience se construit à partir de ces données pour corriger l'organisation. Il ne doit pas conduire à harmoniser artificiellement les versions des témoins. Chaque personne conserve ses observations propres, y compris lorsqu'elles diffèrent ou comportent une limite de visibilité."""),
    ], example('Une porte trouvée ouverte à la relève', """À 6 h 10, vous constatez une porte technique entrouverte. Le collègue sortant pense qu'un prestataire a terminé une intervention, mais ne l'a pas vu sortir. Vous vérifiez l'état du secteur selon la consigne, signalez l'anomalie et demandez la confirmation de maintenance. Vous ne transformez pas cette supposition en accusation.

La trace finale mentionne l'heure du constat, le lieu, les vérifications, l'interlocuteur appelé et la consigne provisoire. Lorsque la maintenance confirme ensuite une intervention, cette information est ajoutée avec son origine et son heure. La relève suivante sait ce qui a été établi et ce qui doit encore être corrigé. Les trois équipes partagent ainsi une information exploitable sans effacer l'incertitude initiale."""),
    ['Type d’information', 'Formulation utile'], [
        ['Observation', 'J’ai constaté la porte ouverte à 6 h 10.'],
        ['Témoignage', 'Le technicien indique avoir quitté le secteur à 5 h 50.'],
        ['Incertitude', 'L’auteur et la cause de l’ouverture ne sont pas établis.'],
        ['Action en attente', 'Maintenance sollicitée ; contrôle demandé à la relève.']],
    ['Distinguer constat, témoignage et hypothèse.', 'La protection et l’alerte précèdent la rédaction.', 'Une correction doit rester traçable.', 'Toute action en attente a un responsable et un relais.'],
    'Le rapport doit partir vite', 'Le responsable vous demande une synthèse alors que l’origine d’une alarme reste inconnue.', [
        question('Que précisez-vous sur la cause ?', 'Qu’elle n’est pas établie à ce stade.', 'La cause la plus probable comme une certitude.', 'Rien, en supprimant toute mention de l’alarme.', 'Une incertitude explicite évite d’orienter à tort le traitement.'),
        question('Vous retrouvez une heure plus exacte après transmission. Que faites-vous ?', 'Ajouter une correction traçable dans le dispositif prévu.', 'Effacer silencieusement l’ancienne trace.', 'Demander aux témoins d’adopter l’heure initiale.', 'La correction doit conserver la fiabilité et l’historique de l’information.'),
        question('Quelle donnée clôt utilement la relève ?', 'L’action restante, son responsable et la consigne applicable.', 'La seule formule « à suivre ».', 'Une liste de suppositions sans destinataire.', 'Un suivi concret évite qu’une anomalie soit oubliée entre deux vacations.')], [
        question('Comment présenter ce qu’un témoin a déclaré ?', 'En attribuant clairement l’information au témoin.', 'Comme une observation personnelle.', 'Comme une vérité judiciaire définitive.', 'L’origine d’une information est nécessaire à son appréciation.'),
        question('Quelle priorité s’impose pendant un incident urgent ?', 'Protéger et alerter avant de détailler le rapport.', 'Terminer la mise en page de la main courante.', 'Attendre tous les témoignages avant d’appeler.', 'Le compte rendu ne doit pas retarder les actions urgentes.'),
        question('Une vidéo utile peut-elle être copiée sur votre téléphone personnel ?', 'Non, sa préservation suit la procédure et les habilitations.', 'Oui, si elle est ensuite supprimée.', 'Oui, dès qu’un collègue la demande.', 'La copie personnelle fragilise la confidentialité et la traçabilité.')])


add('04', 1, 'Comprendre ce qui fait naître et monter un conflit',
    'Identifier les facteurs de tension et intervenir sur l’organisation avant que le désaccord devienne une agression.',
    'revision_theorique', [CONFLITS, 'https://www.inrs.fr/risques/agressions-violences-externes/facteurs-risque.html'], [
    sec('Observer la situation avant de juger la personne', """Un conflit naît souvent d'un écart entre une attente et la réponse obtenue. Un visiteur pensait entrer immédiatement ; la liste n'est pas à jour. Un salarié arrive en retard ; son badge ne fonctionne plus. L'émotion peut augmenter avec l'attente, la fatigue, le bruit, la douleur ou le sentiment d'être traité injustement. Reconnaître ces facteurs n'excuse pas une agression. Cela aide à intervenir sur ce qui peut être corrigé avant que la relation se dégrade. Demandez ce qui bloque concrètement au lieu de qualifier immédiatement la personne de difficile.

L'agent expérimenté possède des repères utiles, mais peut aussi interpréter trop vite. Un regard évité, une agitation ou un ton inhabituel ne prouve pas une intention violente. Le handicap, une difficulté linguistique, un problème de santé ou une inquiétude peuvent modifier la communication. Décrivez ce qui change : volume de voix, rapprochement, gestes menaçants, objets jetés, refus de reculer. C'est la combinaison des faits et de leur évolution qui oriente la protection, pas une lecture supposée de la personnalité."""),
    sec('Agir sur les causes accessibles', """La prévention commence dans l'organisation de l'accueil. Une règle visible, un délai annoncé honnêtement, une file lisible et un interlocuteur de recours réduisent les malentendus. Si deux agents donnent des consignes différentes, l'usager peut percevoir la décision comme arbitraire. Harmonisez les messages pendant le briefing et identifiez la procédure pour les exceptions. Un affichage n'est utile que s'il peut être compris dans les conditions réelles : éclairage, langue, taille du texte, emplacement et accessibilité du passage comptent.

Lorsque l'attente s'allonge, informez avant que le public ne réclame. Ne promettez pas un délai que vous ne maîtrisez pas. Une formule précise comme « le responsable vérifie votre inscription ; je reviens vers vous dès sa réponse » vaut mieux qu'une succession de « dans une minute ». Proposez une option réellement possible : attendre hors de la file, contacter l'organisateur ou utiliser un accès adapté. L'agent ne doit pas négocier une règle de sécurité essentielle, mais peut souvent améliorer la façon de l'appliquer."""),
    sec('Reconnaître le moment du relais', """Le conflit peut rester un désaccord verbal, devenir une agression verbale puis présenter un risque physique. Cette progression n'est pas systématique : certains incidents sont soudains. Maintenez une attention à l'environnement et aux autres personnes. Un seul agent ne doit pas absorber toute son attention dans la discussion pendant qu'un accès est abandonné. Convenez d'un signal de renfort et d'une répartition entre dialogue, surveillance et protection de la file. Si des menaces précises ou un danger immédiat apparaissent, la mise en sécurité et l'alerte priment.

Après un incident, recherchez ce qui a rendu la situation difficile plutôt que de conclure « le public est comme ça ». La durée d'attente, une panne récurrente, une consigne contradictoire ou un poste isolé peuvent être corrigés. Les agressions ne sont pas un passage obligé du métier. Signalez-les selon la procédure, y compris lorsqu'elles n'ont pas provoqué de blessure. L'encadrement doit pouvoir repérer les situations exposantes et organiser une prévention. Le MAC est l'occasion de partager des expériences sans banaliser les comportements subis ni installer des stéréotypes sur les usagers."""),
    ], example('La liste d’accès n’a pas été actualisée', """Un prestataire revient pour la troisième fois au poste parce que son nom n'apparaît pas sur la liste. Il parle fort et vous reproche de lui faire perdre son contrat. Vous identifiez d'abord le problème concret : il a un ordre d'intervention, mais le service demandeur n'a pas transmis l'autorisation. Vous maintenez la règle d'accès et appelez le responsable prévu.

Vous lui proposez d'attendre dans une zone qui ne bloque pas la file et annoncez l'étape de vérification. À la relève, vous signalez l'anomalie d'organisation plutôt que « prestataire agressif » seulement. L'incident n'a pas disparu du seul fait qu'il s'est calmé ; corriger la transmission de liste permettra d'éviter sa répétition."""),
    ['Facteur de tension', 'Action de prévention'], [
        ['Attente sans information', 'Annoncer les étapes et actualiser le message.'],
        ['Consignes différentes', 'Harmoniser le briefing et identifier le décideur.'],
        ['File encombrée', 'Rendre les flux lisibles et protéger les passages.'],
        ['Menaces ou rapprochement dangereux', 'Demander du renfort et organiser la protection.']],
    ['Comprendre une cause n’excuse pas une violence.', 'Les signes doivent être observés sans stéréotype.', 'Une organisation cohérente prévient les tensions.', 'Les agressions doivent être remontées pour être prévenues.'],
    'La troisième attente', 'Un prestataire doit refaire la même vérification et commence à crier.', [
        question('Quelle question aide le mieux ?', 'Identifier ce qui n’a pas été résolu dans son autorisation.', 'Lui demander pourquoi il est toujours désagréable.', 'Conclure qu’il cherche forcément à forcer l’accès.', 'Chercher le blocage concret permet une réponse sans jugement.'),
        question('La vérification prend du temps. Quel message convient ?', 'Expliquer l’étape en cours sans promettre un délai inconnu.', 'Promettre une minute pour qu’il cesse de parler.', 'Ne plus lui répondre jusqu’au résultat.', 'Une information honnête réduit les attentes déçues.'),
        question('Quelle donnée est utile au retour d’expérience ?', 'La répétition des listes non actualisées et les effets sur l’accueil.', 'L’origine supposée du prestataire.', 'La conclusion que tout le public est difficile.', 'Une cause organisationnelle peut faire l’objet d’une correction concrète.')], [
        question('Un regard fuyant prouve-t-il une intention malveillante ?', 'Non, il doit être replacé dans un ensemble de faits.', 'Oui, pour un agent expérimenté.', 'Oui, si la personne parle peu.', 'Un signe isolé peut avoir de nombreuses explications.'),
        question('Quel élément réduit les conflits à l’accès ?', 'Des consignes cohérentes entre agents.', 'Des règles différentes selon l’agent disponible.', 'Un délai volontairement sous-estimé.', 'La cohérence rend la décision compréhensible et moins arbitraire.'),
        question('Quand faut-il signaler une agression verbale ?', 'Selon la procédure, même sans blessure.', 'Uniquement si elle apparaît dans une vidéo.', 'Jamais, car elle fait nécessairement partie du métier.', 'Le signalement permet d’évaluer et de prévenir les violences externes.')])

add('04', 2, 'Désamorcer une agression verbale',
    'Utiliser une écoute courte, une reformulation et une limite claire pour éviter l’escalade au poste.',
    'presentiel_preparation', [CONFLITS, DEONTO], [
    sec('Commencer par rendre l’échange possible', """Face à une personne qui élève la voix, votre premier objectif n'est pas de gagner une discussion. Il est de garder une communication possible tout en préservant la sécurité. Parlez lentement, avec des phrases courtes et un volume maîtrisé. Placez-vous de façon à conserver une distance adaptée et une possibilité de retrait. Évitez de désigner la personne du doigt, de la toucher pour la faire taire ou de l'entourer avec plusieurs collègues sans nécessité. La posture doit exprimer une disponibilité professionnelle, sans défi ni familiarité imposée.

Laissez formuler brièvement le problème lorsque la situation le permet. Une écoute de quelques secondes peut éviter de répondre à une demande que vous avez mal comprise. Reformulez le fait utile : « Vous avez un rendez-vous et votre nom n'est pas sur la liste ». Vous ne validez pas les insultes et ne promettez pas l'accès. Vous montrez que le problème a été entendu. Les phrases « calmez-vous » répétées, les moqueries ou les reproches sur l'éducation peuvent accroître le sentiment d'humiliation et fermer l'échange."""),
    sec('Associer une limite à une solution possible', """Une limite efficace porte sur le comportement et la règle, sans attaquer la personne. Vous pouvez dire : « Je peux vérifier avec votre interlocuteur. En revanche, je vous demande de cesser les insultes ». Puis proposez une étape réaliste. Le choix doit rester dans le cadre : attendre une validation, contacter le service, revenir avec le document demandé ou faire intervenir le responsable. Un faux choix, comme obéir immédiatement ou être puni par l'agent, transforme le contrôle en affrontement. N'annoncez pas un pouvoir que vous n'avez pas.

La répétition calme peut être utile lorsque la même demande revient. Gardez le même message, sans multiplier les arguments ni ouvrir une négociation sans fin. Vous pouvez reconnaître l'inconvénient sans renoncer à la règle : « Je comprends que cette attente vous mette en difficulté ; l'autorisation reste nécessaire ». Si vous avez commis une erreur factuelle, corrigez-la clairement. Reconnaître une erreur de liste ou une mauvaise orientation ne vous oblige pas à accepter une agression. Cela peut au contraire rétablir une relation suffisamment stable pour résoudre le problème."""),
    sec('Savoir interrompre la discussion', """Le dialogue n'est pas une obligation de rester exposé. Une menace précise, une tentative de contact violent, l'apparition d'un objet dangereux ou l'impossibilité de préserver votre distance imposent un changement de priorité. Annoncez le relais si cela reste possible, demandez du renfort et mettez les personnes à l'abri. Un collègue prend le contact verbal pendant qu'un autre surveille l'environnement ; plusieurs agents ne doivent pas donner des ordres contradictoires. L'appel aux forces de l'ordre suit la nature et l'urgence du danger.

La mise en pratique avec le formateur permet de tester le ton, les mots et le positionnement dans des contextes variés. L'objectif n'est pas d'apprendre une phrase magique applicable à toutes les personnes, mais d'ajuster votre communication en gardant les mêmes limites. Après l'exercice, examinez ce qui a permis l'apaisement ou aggravé l'échange. Dans un incident réel, la trace doit mentionner les menaces utiles et les réponses données sans reproduire inutilement des insultes. Le soutien de l'équipe après une agression fait partie de la prévention, tout comme la cohérence de la réponse pendant les faits."""),
    ], example('Une visiteuse affirme que vous lui faites perdre son rendez-vous', """Une visiteuse vous insulte parce que son contact ne répond pas. Vous reformulez le problème, puis expliquez l'étape : le service doit confirmer l'accueil. Vous lui proposez d'attendre dans l'espace prévu pendant que vous tentez le numéro de secours. Vous ajoutez une limite sur les insultes, sans commenter sa personnalité.

Elle continue à protester, mais garde sa distance. Vous répétez le même message sans ajouter de menace. Quand un collègue arrive, vous lui transmettez rapidement le point bloquant pour éviter une nouvelle explication contradictoire. Le résultat recherché est un traitement sécurisé du rendez-vous. Vous n'avez pas besoin que la visiteuse admette publiquement avoir eu tort pour terminer professionnellement l'échange."""),
    ['Étape de dialogue', 'Exemple de formulation'], [
        ['Écouter et reformuler', 'Vous avez rendez-vous et l’accueil n’est pas confirmé.'],
        ['Expliquer la règle', 'L’autorisation du service est nécessaire pour cette zone.'],
        ['Poser une limite', 'Je peux vous aider ; je vous demande de cesser les insultes.'],
        ['Proposer une suite', 'Je contacte le responsable prévu et vous informe de sa réponse.']],
    ['Reformuler ne signifie pas céder.', 'La limite porte sur le comportement.', 'Une solution proposée doit être réalisable.', 'Le danger impose le relais et la protection.'],
    'Le rendez-vous bloqué', 'Une visiteuse en retard vous interpelle agressivement devant la file.', [
        question('Quelle entrée de dialogue est adaptée ?', 'Reformuler son problème et annoncer la vérification possible.', 'Lui répondre qu’elle est mal élevée.', 'Exiger des excuses avant toute information.', 'Une reformulation factuelle ouvre une résolution sans valider les insultes.'),
        question('Elle répète sa demande d’accès immédiat. Que faites-vous ?', 'Rappeler calmement la règle et l’étape en cours.', 'Ajouter une nouvelle menace à chaque répétition.', 'Promettre l’accès pour obtenir le silence.', 'La cohérence évite de transformer la règle en négociation émotionnelle.'),
        question('Elle tente soudain de vous frapper. Quelle priorité change ?', 'Se protéger, protéger les tiers et demander le relais urgent.', 'Continuer le même argumentaire sans changer de position.', 'Filmer l’échange avant d’appeler.', 'Le passage au danger physique impose une réponse de protection.')], [
        question('À quoi sert une reformulation ?', 'Montrer que le problème concret a été compris.', 'Admettre que les insultes sont légitimes.', 'Garantir que la personne obtiendra ce qu’elle demande.', 'Comprendre la demande et valider un comportement sont deux choses différentes.'),
        question('Quelle limite convient ?', 'Demander l’arrêt des insultes en restant disponible pour la procédure.', 'Qualifier la personne d’incapable.', 'Menacer d’une peine judiciaire immédiate.', 'La limite doit être professionnelle, réaliste et centrée sur le comportement.'),
        question('Combien d’agents doivent donner simultanément des consignes contradictoires ?', 'Aucun ; les rôles et le message doivent être coordonnés.', 'Tous pour montrer la force de l’équipe.', 'Deux minimum, même si leurs objectifs diffèrent.', 'Un interlocuteur principal et des rôles clairs réduisent la confusion.')])

add('04', 3, 'Maîtriser ses émotions et coordonner le relais',
    'Repérer sa propre montée de tension et organiser un relais qui protège l’agent, les collègues et le public.',
    'presentiel_preparation', [CONFLITS, 'https://www.inrs.fr/risques/agressions-violences-externes/ce-qu-il-faut-retenir'], [
    sec('L’agent fait partie de la situation', """La tension du public peut modifier votre propre comportement : voix plus forte, gestes rapides, respiration courte, pensée centrée sur une seule personne, besoin d'avoir le dernier mot. Repérer ces signes permet de reprendre une marge de décision. Il ne s'agit pas de supprimer toute émotion, mais d'éviter qu'elle commande une action incompatible avec la mission. Un agent expérimenté peut être plus vulnérable après une nuit difficile, plusieurs incidents ou un conflit personnel. Le reconnaître constitue une compétence professionnelle.

Utilisez les moyens simples compatibles avec la situation : ralentir une phrase, relâcher une tension corporelle, garder une distance, revenir à la consigne et demander un relais. Une respiration maîtrisée peut aider à retrouver un débit de parole, mais elle ne remplace pas la mise en sécurité si le danger augmente. Ne restez pas seul dans une interaction devenue personnelle pour préserver votre image. L'objectif est que l'équipe assure la mission dans de bonnes conditions, pas que chaque agent démontre qu'il peut tout gérer sans aide."""),
    sec('Préparer un relais qui n’aggrave pas le conflit', """Le renfort doit avoir une fonction claire. Un collègue peut reprendre le dialogue, surveiller la file, maintenir un accès dégagé ou appeler les forces compétentes. Son arrivée ne doit pas être mise en scène comme une menace destinée à humilier l'usager. Transmettez brièvement le fait bloquant, la règle et ce qui a déjà été proposé. Le nouvel interlocuteur évite ainsi de recommencer toute la discussion ou de contredire une décision sans la comprendre. Un changement de voix peut suffire à sortir d'une relation trop personnalisée.

Convenez des signaux et des limites pendant le briefing : quand demander un relais, quel canal utiliser, où se replier, qui reste au contrôle d'accès ? Une phrase ou un code incompris ne fonctionne pas. Vérifiez aussi les contraintes du travail isolé et les moyens d'alerte disponibles. Une organisation reposant sur un collègue théoriquement présent mais inaccessible à la radio doit être corrigée. Le droit au retrait d'une situation dangereuse et les procédures d'alerte relèvent de cadres précis que l'employeur doit expliquer ; ne les remplacez pas par une consigne informelle de « tenir quoi qu'il arrive »."""),
    sec('Après une agression, ne pas banaliser', """Une fois le danger écarté, vérifiez l'état physique et psychologique des personnes, faites prendre en charge les blessures ou malaises et informez l'encadrement. Un agent peut paraître calme immédiatement puis ressentir une difficulté plus tard. Le soutien ne consiste pas à le forcer à raconter devant tout le monde. Proposez le relais prévu, le service de prévention et de santé au travail ou les ressources de l'entreprise. Les démarches de signalement et les suites éventuelles doivent être expliquées sans culpabilisation.

Le débriefing distingue ce qui a été observé de ce que chacun a ressenti. Il sert à comprendre les points de décision : appel trop tardif, accès mal protégé, consigne incohérente, fatigue, isolement ou absence de rôle défini. Les échanges ne doivent pas conduire à fabriquer une version commune qui efface les observations individuelles. Dans les ateliers MAC, les jeux de rôle permettent d'entraîner le relais, puis de comparer les effets d'une intervention coordonnée avec ceux d'un groupe d'agents parlant en même temps. L'évaluation porte sur la protection et la cohérence, pas sur la domination de l'usager."""),
    ], example('Votre collègue s’énerve à son tour', """Vous entendez votre collègue répéter la même phrase de plus en plus fort face à un visiteur. La file se rapproche et le contrôle d'accès n'est plus surveillé. Vous annoncez calmement que vous reprenez la vérification du dossier. Votre collègue vous transmet le problème puis se place sur une autre tâche, sans lancer une dernière remarque.

Vous maintenez la règle déjà expliquée et redonnez une option claire au visiteur. Après l'incident, vous faites un point à l'écart sur les signes de tension et le moment du relais. Le collègue n'a pas « perdu » la confrontation : l'équipe a retrouvé une capacité de décision. Vous identifiez également le manque d'effectif à l'heure d'affluence pour le remonter au responsable."""),
    ['Signal ou besoin', 'Réponse utile'], [
        ['Voix qui monte, discours répétitif', 'Ralentir, revenir aux faits et envisager le relais.'],
        ['Attention absorbée par un seul usager', 'Répartir dialogue et surveillance du secteur.'],
        ['Renfort demandé', 'Donner une tâche et un contexte précis.'],
        ['Après l’agression', 'Soutien, signalement et retour d’expérience respectueux.']],
    ['Demander un relais est une décision professionnelle.', 'Le renfort doit avoir un rôle précis.', 'Ne pas rester exposé pour préserver son image.', 'Une agression mérite un suivi, même sans blessure visible.'],
    'La discussion devient personnelle', 'Vous sentez que vous cherchez désormais à avoir le dernier mot alors que l’usager continue à protester.', [
        question('Quel signe reconnaissez-vous ?', 'Une montée de tension qui peut réduire votre jugement.', 'La preuve qu’il faut accélérer la confrontation.', 'Une raison suffisante pour abandonner toutes les règles.', 'Identifier sa propre tension permet de préserver la qualité de décision.'),
        question('Comment demander le relais ?', 'Transmettre le problème, la règle et la tâche à reprendre.', 'Appeler plusieurs collègues sans leur expliquer la situation.', 'Inviter le collègue à faire peur à l’usager.', 'Un relais utile repose sur une information courte et des rôles coordonnés.'),
        question('Quelle attitude après l’incident ?', 'Débriefer les faits et les points d’amélioration sans humiliation.', 'Se moquer de celui qui a demandé de l’aide.', 'Accorder les versions pour éliminer les erreurs.', 'Le retour d’expérience vise l’amélioration et respecte les observations de chacun.')], [
        question('Quel objectif guide un relais ?', 'Maintenir la sécurité et la cohérence de la mission.', 'Montrer qu’un agent est supérieur à l’autre.', 'Obtenir une humiliation publique du visiteur.', 'Le relais répond à une nécessité collective de protection.'),
        question('La respiration maîtrisée remplace-t-elle la protection face à un danger immédiat ?', 'Non, elle peut aider mais la mise en sécurité reste prioritaire.', 'Oui, quelle que soit la menace.', 'Oui, si l’agent connaît bien le public.', 'Un outil de maîtrise émotionnelle ne supprime pas le danger extérieur.'),
        question('Que faut-il éviter après une agression ?', 'Forcer l’agent à raconter devant tout le monde.', 'Proposer un soutien adapté.', 'Signaler les facteurs de risque.', 'Le soutien doit respecter la personne et les procédures de prise en charge.')])

add('04', 4, 'Inspection visuelle et fouille des bagages',
    'Distinguer les contrôles, recueillir le consentement nécessaire et gérer un refus sans contrainte illégitime.',
    'presentiel_preparation', [FILTRAGE, 'https://www.service-public.gouv.fr/particuliers/vosdroits/F32041'], [
    sec('Deux actes à ne pas confondre', """L'article L. 613-2 permet aux agents concernés de procéder à l'inspection visuelle des bagages et, avec le consentement de leur propriétaire, à leur fouille. L'inspection consiste à regarder ; la fouille comporte une recherche dans le contenu. La différence a un effet concret sur les gestes autorisés. Annoncez le contrôle, expliquez son objet et faites présenter le bagage de façon adaptée. Ne transformez pas une demande d'ouverture en autorisation implicite de déplacer tous les objets, d'explorer des documents ou de consulter un appareil électronique.

Le consentement à une fouille ne se déduit pas du silence d'une personne intimidée, d'une affiche ou du seul achat d'un billet. Assurez-vous qu'elle comprend ce qui est demandé et respecte les limites du contrôle. Une coopération à une étape ne vaut pas permission pour toutes les suivantes. La recherche reste liée à l'objectif de sécurité du site, dans le cadre légal et les consignes. L'agent ne doit pas commenter la vie privée révélée par le contenu ni montrer les effets personnels aux personnes qui attendent."""),
    sec('Préparer un poste qui respecte les personnes', """Une table stable, un éclairage adapté, une circulation lisible et un espace de contrôle organisé facilitent la présentation du bagage. Le propriétaire garde une relation claire avec ses effets. Les files doivent permettre le passage des autres usagers sans mélange d'objets. Prévoyez le cas d'un traitement médical, d'un objet fragile, d'une difficulté de mobilité ou d'un équipement professionnel. L'objectif est une inspection efficace et respectueuse, pas un déballage public systématique. En cas de doute sur un objet, demandez le relais prévu au lieu d'improviser une expertise.

La présence d'un objet interdit par le règlement ne signifie pas automatiquement infraction pénale. Une bouteille, un outil de travail ou un objet volumineux peut être incompatible avec l'accès tout en étant détenu légalement. Expliquez la solution autorisée : retour au véhicule, consigne disponible ou renoncement à l'entrée, selon le site. Ne vous appropriez pas le bien et ne le détruisez pas. Si l'objet présente un danger suspect, la priorité devient la protection, la mise à distance et l'alerte ; il ne faut pas le manipuler pour prouver son caractère dangereux."""),
    sec('Traiter un refus avec une règle licite', """Un refus de contrôle n'autorise ni la fouille forcée ni la rétention automatique. Expliquez les conséquences prévues par le cadre applicable à l'accès et demandez le responsable si nécessaire. Le refus peut conduire à ne pas autoriser l'entrée lorsque la mesure est légalement applicable, mais il ne permet pas de retenir la personne qui souhaite repartir sans autre fondement. Ne bloquez pas toutes les issues pour obtenir le consentement. L'agent doit préserver la possibilité de comprendre, de choisir et de contester par un canal approprié.

La pratique encadrée permet de travailler la présentation, la communication, le positionnement et la gestion des objets sans porter atteinte aux personnes. Les exercices doivent distinguer bagage ordinaire, refus, objet interdit sans danger immédiat et découverte préoccupante. À la relève, tracez uniquement ce qui a un intérêt pour la mission : motif objectif, règle expliquée, relais et suite. Une longue description du contenu privé d'un sac n'est pas nécessaire lorsque le contrôle n'a révélé aucun incident. Le professionnalisme se mesure à la qualité du contrôle autant qu'au respect de ses limites."""),
    ], example('Un outil dans le sac d’un technicien', """Un technicien se présente à un événement avec un outil nécessaire à une intervention, mais non admis par l'accès public. Vous distinguez son droit de posséder cet outil de la règle d'entrée. Vous contactez le responsable technique afin de vérifier l'accès professionnel prévu et l'autorisation de mission.

Vous ne confisquez pas l'outil et ne supposez pas une intention malveillante du seul fait de sa présence. Si aucune autorisation n'est confirmée, vous expliquez l'option prévue par l'organisateur. Si un élément révèle un danger immédiat, le raisonnement change vers la protection et l'alerte. Le même objet peut donc demander des décisions différentes selon le contexte, les autorisations et les faits observés."""),
    ['Action ou situation', 'Cadre à respecter'], [
        ['Inspection visuelle', 'Regarder le contenu présenté sans glisser vers une fouille.'],
        ['Fouille', 'Consentement du propriétaire et recherche limitée à la mission.'],
        ['Objet interdit par le site', 'Solution prévue sans appropriation arbitraire.'],
        ['Refus', 'Expliquer le cadre d’accès ; aucune fouille forcée automatique.']],
    ['Inspection et fouille sont deux actes distincts.', 'Le consentement doit correspondre à l’acte demandé.', 'Objet interdit sur le site ne signifie pas forcément objet illégal.', 'Un refus ne crée pas un droit automatique de rétention.'],
    'Le visiteur accepte d’ouvrir mais refuse la fouille', 'Le sac est ouvert, mais son propriétaire refuse que vous déplaciez les objets.', [
        question('Comment interpréter sa position ?', 'L’ouverture ne vaut pas consentement à toute recherche dans le sac.', 'Toute ouverture autorise une fouille complète.', 'Le refus prouve automatiquement un délit.', 'Le périmètre du consentement doit être respecté.'),
        question('Quelle réponse convient ?', 'Expliquer la règle d’accès applicable et solliciter le responsable si besoin.', 'Saisir le sac pour terminer rapidement.', 'Empêcher la personne de repartir jusqu’à son accord.', 'Le refus se gère dans le cadre d’accès, sans contrainte arbitraire.'),
        question('Quelle trace conserver si un incident survient ?', 'Le contrôle proposé, le refus et la suite décidée.', 'Tous les objets personnels aperçus sans lien avec l’incident.', 'Une conclusion automatique de culpabilité.', 'La trace reste factuelle et proportionnée à la mission.')], [
        question('Quel acte nécessite le consentement du propriétaire selon L. 613-2 ?', 'La fouille du bagage.', 'Le simple fait pour l’agent de porter son uniforme.', 'La lecture du panneau d’accueil.', 'Le texte distingue inspection visuelle et fouille avec consentement.'),
        question('Un objet interdit par le règlement est-il toujours détenu illégalement ?', 'Non, la règle d’accès et la légalité de détention sont distinctes.', 'Oui, dans tout établissement privé.', 'Oui, dès que l’agent l’a vu.', 'Un objet peut être légal mais incompatible avec l’entrée sur un site.'),
        question('Que faire d’un objet potentiellement dangereux et suspect ?', 'Éviter sa manipulation, protéger et alerter selon la procédure.', 'Le transporter au poste pour l’examiner.', 'Le donner à un visiteur pour le sortir.', 'Le déplacement ou la manipulation peut créer une nouvelle exposition.')])

add('04', 5, 'Palpations : vérifier le cadre et préserver le consentement',
    'Identifier les conditions légales et individuelles d’une palpation et préparer sa réalisation encadrée.',
    'presentiel_preparation', [FILTRAGE, 'https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000047569772', 'https://www.cnaps.interieur.gouv.fr/Actualites/Les-agrements-a-la-palpation-evoluent', 'https://www.service-public.gouv.fr/particuliers/vosdroits/F32041'], [
    sec('Le besoin de sécurité ne suffit pas à autoriser le geste', """La palpation de sécurité est un contrôle corporel de sécurité, distinct d'une fouille du corps et du contrôle d'un bagage. Elle n'est pas une prérogative générale utilisable à chaque entrée. L'article L. 613-2 vise notamment des circonstances particulières de menace grave constatées dans le cadre prévu ou l'existence d'un périmètre de protection. L'article L. 613-3 prévoit un autre cadre pour certaines manifestations sportives, récréatives ou culturelles rassemblant plus de trois cents spectateurs, sous le contrôle d'un officier de police judiciaire et dans les conditions du texte. L'agent doit connaître le dispositif où il intervient, ses lieux, sa durée et les personnes chargées de son organisation.

Le CNAPS précise que les agents de sécurité privée titulaires de la carte professionnelle n'ont plus à obtenir d'agrément spécifique supplémentaire pour les palpations depuis la loi du 25 mai 2021. Le régime des membres du service d'ordre de l'organisateur est distinct et ne doit pas être confondu avec celui des agents APS. La hiérarchie vérifie néanmoins le statut, la formation et toutes les conditions du dispositif applicable. La carte APS n'autorise donc pas une palpation partout. Une affiche ou une demande du client ne remplace pas le fondement légal. En cas de document absent ou de doute, faites clarifier la situation avant de pratiquer."""),
    sec('Un consentement exprès et une personne de même sexe', """Le consentement à la palpation doit être exprès. La personne doit comprendre le contrôle demandé et manifester son accord ; le silence, la surprise ou la pression ne suffisent pas. La palpation doit être réalisée par une personne du même sexe, conformément au cadre légal. Organisez les effectifs et le parcours afin que cette condition soit effectivement réalisable. L'affluence n'autorise pas à la supprimer. Si la situation d'une personne appelle une précaution particulière, traitez-la avec discrétion et sollicitez le responsable pour une solution respectueuse du droit et de la dignité.

Annoncez la nature du contrôle, sa finalité et la manière de signaler une difficulté. Les gestes relèvent d'une technique professionnelle enseignée et contrôlée en présentiel ; cette leçon ne constitue pas une autorisation de s'exercer sur quelqu'un. La palpation ne doit pas devenir une fouille intrusive, une recherche de documents ou un geste humiliant. Un problème médical, une douleur ou un appareillage demande une adaptation prévue, sans exposition publique de données de santé. La personne doit rester un interlocuteur et ne pas être traitée comme un obstacle à faire passer plus vite."""),
    sec('Refus, interruption et découverte', """Si le consentement n'est pas donné ou est retiré, vous ne forcez pas le contrôle. Appliquez les conséquences d'accès prévues par le cadre légal et les consignes, expliquez-les et organisez le relais. Le refus ne prouve pas une infraction et ne justifie pas à lui seul une privation de liberté. Une file qui s'impatiente ne doit pas conduire à accélérer les gestes ou à supprimer l'explication. Un poste correctement préparé prévoit une zone de dialogue et une personne responsable pour éviter que chaque cas bloque le dispositif.

Si le contrôle fait apparaître un risque, arrêtez l'improvisation : protégez les personnes, demandez le renfort adapté et suivez la procédure. L'agent n'essaie pas de manipuler un objet suspect pour l'identifier précisément. La pratique avec le formateur travaille le placement, la méthode, la communication, le consentement et les cas d'arrêt. Au débriefing, vérifiez autant la conformité du cadre que la qualité du geste. Une palpation techniquement bien réalisée mais dépourvue de fondement ou de consentement reste un échec professionnel. L'objectif est un contrôle sûr, légal et respectueux."""),
    ], example('Il manque un agent pour la file', """Un dispositif comporte plusieurs files et une personne se présente alors qu'aucun agent du même sexe n'est disponible au poste. Le responsable de file demande de continuer pour réduire l'attente. Vous suspendez cette étape et sollicitez l'organisation prévue : agent disponible sur une autre ligne ou relais du responsable.

Vous expliquez l'attente sans détailler publiquement la situation personnelle du visiteur. Vous ne remplacez pas la palpation par une fouille improvisée et ne présentez pas l'affluence comme une exception légale. Après l'événement, le manque d'effectif adapté est intégré au retour d'expérience. Le contrôle futur doit être organisé pour rendre les exigences applicables, pas pour espérer les contourner au dernier moment."""),
    ['Condition', 'Vérification avant ou pendant le contrôle'], [
        ['Fondement', 'Dispositif légal, lieux et durée identifiés.'],
        ['Situation individuelle', 'Formation et conditions propres au cadre vérifiées.'],
        ['Consentement', 'Accord exprès pour la palpation, sans contrainte.'],
        ['Réalisation', 'Agent du même sexe et technique encadrée respectueuse.']],
    ['La palpation n’est pas autorisée partout.', 'Le consentement exprès est indispensable.', 'L’affluence ne supprime pas la condition de même sexe.', 'Le cadre juridique et le geste pratique doivent tous deux être maîtrisés.'],
    'L’affluence met le contrôle sous pression', 'Une file s’allonge et le responsable propose de simplifier les étapes de palpation.', [
        question('Peut-on supprimer la demande de consentement ?', 'Non, l’accord exprès reste nécessaire.', 'Oui, si un panneau mentionne les contrôles.', 'Oui, lorsque le billet a été acheté en ligne.', 'Ni l’affiche ni le billet ne remplacent le consentement exprès à la palpation.'),
        question('Aucun agent du même sexe n’est disponible. Que faites-vous ?', 'Demander le relais prévu sans réaliser une palpation non conforme.', 'Continuer pour ne pas pénaliser la file.', 'Demander à un visiteur de réaliser le geste.', 'L’organisation doit permettre le respect de la condition légale.'),
        question('La personne retire son accord. Quelle décision convient ?', 'Arrêter le contrôle et appliquer le cadre d’accès prévu.', 'Finir parce que l’accord initial suffit pour toute la durée.', 'La retenir automatiquement au poste.', 'Le retrait du consentement ne doit pas être contourné par une contrainte.')], [
        question('La carte APS suffit-elle pour pratiquer une palpation dans tout lieu ?', 'Non, le cadre de la mission et ses conditions doivent être réunis.', 'Oui, dès qu’un client le souhaite.', 'Oui, pour un agent ayant déjà fait du filtrage.', 'Le besoin de sécurité et l’expérience ne créent pas une compétence générale.'),
        question('Quelle forme d’accord est requise ?', 'Un consentement exprès à la palpation.', 'Le silence d’une personne qui attend.', 'L’accord d’un autre visiteur.', 'L’accord doit venir de la personne concernée et porter sur le contrôle demandé.'),
        question('Que doit vérifier la pratique avec le formateur ?', 'Le cadre, le consentement, la communication et la technique.', 'Uniquement la rapidité du passage.', 'La capacité à obtenir l’accord par intimidation.', 'La conformité d’une palpation ne se réduit pas à la vitesse ou à la gestuelle.')])

add('04', 6, 'Organiser un filtrage cohérent, y compris les véhicules',
    'Préparer les flux, traiter les anomalies d’accès et appliquer les limites de l’inspection visuelle des véhicules.',
    'presentiel_preparation', [FILTRAGE, 'https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000054718795', REFLEXES], [
    sec('Préparer l’ensemble du parcours', """Un filtrage efficace commence avant le premier contrôle. Repérez les entrées, sorties, cheminements de secours, zones d'attente et accès professionnels. Vérifiez que les équipements fonctionnent, que les listes sont à jour et qu'un responsable peut décider des cas non prévus. La file ne doit pas obstruer une issue ou mélanger piétons et véhicules. Chaque agent doit connaître sa tâche et le signal de renfort. L'objectif n'est pas seulement de faire passer un nombre de personnes, mais de maintenir un dispositif compréhensible et sûr à tout moment.

Les contrôles doivent être cohérents entre les files et accessibles aux personnes qui ont besoin d'une adaptation. Une personne accompagnée, un matériel médical, un prestataire attendu ou une livraison en retard ne se traite pas par une règle improvisée. Séparez la vérification de l'autorisation et la gestion du flux : on peut déplacer une discussion vers un espace prévu sans accorder l'accès. Ne faites pas patienter un usager dans un endroit qui l'expose à la circulation. Les consignes provisoires doivent être transmises à toute l'équipe et retirées lorsqu'elles ne s'appliquent plus."""),
    sec('L’inspection des véhicules possède un cadre spécifique', """Depuis le 20 août 2026, l'article L. 613-2-1 encadre l'inspection visuelle des véhicules et de leurs coffres par les agents concernés. Il prévoit notamment la demande du gestionnaire et le consentement exprès du conducteur, pour les lieux et conditions qu'il désigne. Sont exclus les véhicules spécialement aménagés à usage d'habitation. Le texte vise certaines catégories d'établissements, d'événements et de lieux sensibles ; d'autres lieux peuvent être concernés par une autorisation préfectorale dans les circonstances prévues. Il ne crée pas un droit de contrôler tous les véhicules sur n'importe quel parking.

La mission reste une inspection visuelle, pas une fouille générale du véhicule, un démontage ou une exploration des effets privés sans fondement. Avant la vacation, l'employeur doit préciser la catégorie de site, les documents applicables et les modalités de contrôle. En cas de refus dans ce cadre, l'accès du véhicule est interdit, sans supprimer par principe la possibilité pour le conducteur et ses passagers d'accéder au site sans véhicule. L'accès piéton reste soumis à ses propres règles. Cette distinction doit apparaître dans l'explication, afin de ne pas transformer un refus d'inspection en exclusion automatique de toute personne."""),
    sec('Gérer une anomalie sans désorganiser le dispositif', """Une autorisation manquante, un objet interdit ou une panne doivent déclencher un circuit connu. Faites confirmer la décision utile, maintenez la séparation des flux et conservez un passage pour les secours. Si le risque augmente, la protection et l'alerte deviennent prioritaires. Ne poursuivez pas un véhicule et ne vous placez pas devant lui pour imposer votre autorité. Les moyens matériels de protection et les procédures de fermeture relèvent de l'organisation du site ; l'agent applique ceux qui sont prévus et qu'il maîtrise, sans improvisation dangereuse.

La fin de vacation comprend un point sur les accès restés ouverts, les autorisations en attente, les objets pris en consigne selon la procédure et les anomalies de matériel. Une fermeture oubliée peut annuler tout le travail de filtrage. Le retour d'expérience vérifie la clarté des messages, l'adaptation des effectifs et la gestion des heures d'affluence. En présentiel, les scénarios combinent public, véhicule, refus et arrivée d'un secours pour entraîner les priorités. Le succès consiste à préserver la cohérence du dispositif, même lorsqu'une exception ou un incident perturbe le déroulement prévu."""),
    ], example('Un conducteur refuse l’inspection visuelle', """Sur un site relevant du cadre légal prévu et dont les conditions ont été vérifiées, un conducteur refuse l'inspection de son coffre. Vous expliquez que le véhicule ne peut pas accéder dans ces conditions. Vous indiquez l'option de stationnement extérieur autorisée et l'accès piéton, soumis au contrôle habituel, si cette solution est possible.

Vous n'ouvrez pas le coffre de force et n'annoncez pas que toute la famille est désormais interdite de site. Un collègue maintient la circulation pendant que vous orientez le conducteur vers un espace sûr. L'événement est tracé avec son motif et sa suite, sans diagnostic sur l'intention du conducteur. L'exercice montre l'intérêt de prévoir une zone de résolution avant le portail."""),
    ['Élément du filtrage', 'Contrôle de cohérence'], [
        ['Flux', 'Piétons, véhicules et secours disposent de passages adaptés.'],
        ['Exception d’accès', 'Un décideur et une zone de résolution sont identifiés.'],
        ['Véhicule', 'Cadre L. 613-2-1, consentement exprès et inspection visuelle seulement.'],
        ['Refus du conducteur', 'Conséquence sur le véhicule et règles piétonnes distinguées.']],
    ['Le filtrage se prépare comme un parcours complet.', 'L’inspection visuelle des véhicules n’est pas un pouvoir général.', 'Les véhicules aménagés à usage d’habitation sont exclus du dispositif décrit.', 'Le refus du véhicule ne supprime pas automatiquement la possibilité d’accès à pied.'],
    'Une file de véhicules se forme', 'Un contrôle est refusé alors que plusieurs véhicules attendent derrière.', [
        question('Quelle condition vérifiez-vous pour ce dispositif ?', 'Que le site et les modalités relèvent du cadre légal applicable.', 'Que le client possède simplement un parking.', 'Que le conducteur semble pressé.', 'L’inspection des véhicules ne découle pas de la seule existence d’un parking.'),
        question('Le conducteur refuse l’inspection. Quelle réponse respecte le cadre décrit ?', 'Refuser l’accès du véhicule et distinguer l’éventuel accès à pied.', 'Ouvrir le coffre de force pour libérer la file.', 'Interdire automatiquement toute entrée aux passagers.', 'Les conséquences du refus doivent respecter la distinction prévue par le texte.'),
        question('Comment maintenir la sécurité de la file ?', 'Orienter vers une zone sûre et faire gérer le flux par le collègue.', 'Se placer devant le véhicule pour l’empêcher de bouger.', 'Laisser les piétons passer entre les véhicules sans organisation.', 'La résolution du cas ne doit pas créer un danger de circulation.')], [
        question('Que permet le cadre décrit par L. 613-2-1 ?', 'Une inspection visuelle des véhicules dans les conditions prévues.', 'Une fouille générale de tous les parkings privés.', 'Le démontage de véhicules sans consentement.', 'Le texte fixe un cadre limité et ne crée pas un pouvoir général de fouille.'),
        question('Quel véhicule est exclu du dispositif décrit ?', 'Un véhicule spécialement aménagé à usage d’habitation.', 'Tout véhicule de couleur sombre.', 'Tout véhicule dont le conducteur vient seul.', 'L’exclusion prévue concerne l’usage d’habitation spécialement aménagé.'),
        question('Quel passage doit rester anticipé dans le filtrage ?', 'L’accès des secours.', 'Uniquement la file la plus rapide.', 'Le passage réservé aux amis de l’équipe.', 'La sécurité du dispositif inclut les interventions d’urgence.')])


add('05', 1, 'Comprendre la menace terroriste et ses formes',
    'Identifier les grandes familles de menaces et leurs conséquences pour la protection, sans chercher à qualifier seul un auteur.',
    'revision_theorique', [VIGI, 'https://www.dgsi.interieur.gouv.fr/decouvrir-dgsi/nos-missions/lutte-contre-terrorisme-et-extremismes-violents/lutte-anti-terroriste', 'https://www.interieur.gouv.fr/actualites/actualites-du-ministere/attentats-du-13-novembre-2015-tirer-lecons-ne-jamais-baisser-garde', 'https://www.interieur.gouv.fr/actualites/actualites-du-ministere/nice-14-juillet-2016-dix-ans-apres-lattentat-nation-se-souvient'], [
    sec('Une violence destinée à produire un effet collectif', """Le terrorisme ne se définit pas par une apparence, une nationalité ou une religion. Le cadre pénal rattache certaines infractions à une entreprise individuelle ou collective ayant pour but de troubler gravement l'ordre public par l'intimidation ou la terreur. L'effet recherché dépasse les victimes directement atteintes : peur, désorganisation, pression sur les institutions et retentissement public. L'agent n'a pas à établir seul cette qualification. Il doit reconnaître une situation dangereuse, protéger et transmettre des faits, même si le mobile reste inconnu.

Les motivations et organisations peuvent varier. Des individus agissent en groupe, d'autres seuls ou sous influence à distance. Une revendication peut être tardive, incertaine ou absente. Ne subordonnez donc pas la réaction de sécurité à la découverte d'un symbole ou d'un discours. Une agression armée ou une explosion appelle une protection immédiate quelle que soit sa qualification future. La recherche du mobile, des liens et de la responsabilité appartient aux services compétents. Cette séparation aide à agir vite sans diffuser une accusation infondée."""),
    sec('Des modes d’action aux conséquences différentes', """Les grandes familles de situations comprennent les attaques armées, les attaques à l'arme blanche, l'emploi de véhicules contre des personnes, les explosions, les prises d'otages et les attaques visant des substances ou systèmes dangereux. Elles n'exigent pas les mêmes précautions d'approche. Une menace nucléaire, radiologique, biologique ou chimique peut être invisible et provoquer une contamination secondaire ; un événement informatique peut perturber des fonctions de sécurité ou faciliter une intrusion. Il faut éviter de réduire la prévention au seul contrôle d'un sac à l'entrée.

L'étude de l'historique sert à comprendre ces différences et l'importance de la coordination. Les attaques de janvier et novembre 2015 en France ont illustré la diversité des lieux touchés et la nécessité d'une réaction collective. L'attentat de Nice du 14 juillet 2016 rappelle qu'un rassemblement peut être exposé à une menace liée aux véhicules. Ces repères ne sont pas des scénarios à reproduire ni une liste qui prédirait la prochaine attaque. Ils nourrissent un raisonnement de protection : accès, alerte, mise à l'abri, secours et soutien aux personnes."""),
    sec('Traduire la connaissance en vigilance utile', """Votre niveau de préparation doit porter sur le site réel : connaître les moyens d'alerte, les accès utilisables par les secours, les options de mise en sécurité et les limites de vos moyens. Un équipement ou une procédure ne suffit pas isolément ; les agents doivent comprendre le rôle de chacun et les conditions d'emploi. La prévention consiste à réduire les occasions de danger et à augmenter la capacité de réaction, sans transformer le public en ensemble de suspects. Les contrôles gardent leurs conditions légales, y compris face à une menace importante.

Une information préoccupante doit être évaluée à partir de sa source, de sa date et des faits. Ne relayez pas une vidéo ancienne comme si elle décrivait une menace immédiate sur votre site. Une rumeur peut provoquer un mouvement de foule et compliquer la réponse. À l'inverse, une absence de revendication ne justifie pas d'attendre face à des tirs ou à des victimes. La compétence recherchée est de reconnaître le danger, de choisir une réponse protectrice et de communiquer avec précision. Le MAC actualise ces réflexes, qui doivent ensuite être exercés avec le formateur et l'organisation du site."""),
    ], example('Des détonations à proximité d’un lieu public', """Pendant un événement, plusieurs détonations sont entendues et des personnes courent vers une sortie. Vous ne savez pas encore s'il s'agit de tirs, d'un accident ou d'un autre phénomène. Vous prenez en compte le danger possible, observez depuis une position sûre et transmettez ce qui est effectivement entendu et vu.

Vous n'annoncez pas sur la radio une identité ou une motivation que personne n'a établie. Les premières décisions portent sur l'exposition du public, la protection et l'alerte. Lorsque des informations fiables arrivent, l'équipe les intègre. L'incertitude sur la qualification ne bloque pas l'action ; elle oblige à rester précis sur les faits et prudent sur les affirmations."""),
    ['Famille de situation', 'Conséquence pour l’agent'], [
        ['Attaque contre des personnes', 'Se protéger, orienter sans exposition et alerter.'],
        ['Objet ou explosion suspecte', 'Éviter approche et manipulation, prévenir les nouvelles expositions.'],
        ['Risque toxique ou contaminant', 'Éviter l’exposition et attendre les consignes spécialisées.'],
        ['Perturbation numérique', 'Signaler et appliquer la continuité prévue, sans improvisation technique.']],
    ['Le terrorisme ne se reconnaît pas à une appartenance supposée.', 'La qualification du mobile relève des autorités.', 'Un danger réel exige une réaction même sans revendication.', 'L’historique sert à améliorer la protection et la coordination.'],
    'Une information encore incomplète', 'Vous recevez deux témoignages différents après des détonations près du site.', [
        question('Faut-il attendre de connaître le mobile pour protéger ?', 'Non, le danger observable suffit à engager la protection adaptée.', 'Oui, sans revendication il n’y a jamais d’urgence.', 'Oui, tant qu’un réseau social ne confirme pas.', 'La protection répond aux faits dangereux, indépendamment de leur qualification future.'),
        question('Que transmettez-vous ?', 'Les faits observés, les témoignages attribués et les inconnues.', 'Une identité supposée à partir de l’apparence.', 'La version la plus spectaculaire.', 'Une transmission fiable distingue les niveaux d’information.'),
        question('Une vidéo ancienne est partagée comme actuelle. Que faites-vous ?', 'Ne pas la relayer et rechercher une source officielle datée.', 'La diffuser à tout le public pour gagner du temps.', 'L’utiliser pour nommer un auteur sans vérification.', 'Une information décontextualisée peut créer de la peur et de mauvaises décisions.')], [
        question('Qu’est-ce qui ne permet pas de définir une menace terroriste ?', 'L’apparence ou la religion supposée d’une personne.', 'Des faits dangereux constatés.', 'Une alerte officielle concernant une situation.', 'La vigilance doit porter sur des faits et non sur une appartenance supposée.'),
        question('Pourquoi étudier les attentats passés ?', 'Pour tirer des enseignements de protection et de coordination.', 'Pour affirmer que la prochaine attaque sera identique.', 'Pour créer des profils d’apparence à contrôler.', 'Le retour historique éclaire les conséquences et les réponses, sans prédiction automatique.'),
        question('Une menace numérique peut-elle concerner la sécurité du site ?', 'Oui, elle peut perturber des fonctions et informations utiles à la protection.', 'Non, seuls les objets matériels concernent l’agent.', 'Non, si le portail physique est fermé.', 'La sécurité du site comprend aussi la fiabilité des systèmes et procédures.')])

add('05', 2, 'Vigipirate 2026 et niveau de vigilance du site',
    'Connaître les stades d’alerte actualisés et les traduire en consignes vérifiées sans créer de nouveaux pouvoirs.',
    'revision_theorique', [VIGI, 'https://www.sgdsn.gouv.fr/vigipirate/le-plan-vigipirate-faire-face-ensemble'], [
    sec('Utiliser les repères de la version 2026', """Le plan Vigipirate associe l'État, les collectivités, les opérateurs et les citoyens dans une démarche de vigilance et de protection. L'édition mise en œuvre à partir du 22 juin 2026 comporte trois stades : vigilance, vigilance renforcée et alerte attentat. Le dernier correspond au stade le plus élevé et peut être activé pour douze jours renouvelables sur décision expresse du Premier ministre. Les supports plus anciens peuvent employer d'autres intitulés ; ils doivent être identifiés comme historiques et ne pas servir de référence opérationnelle actuelle.

Un stade national ne se résume pas à une couleur affichée au poste. Il se traduit par des mesures adaptées aux secteurs, aux lieux et aux circonstances. L'agent consulte la consigne reçue, sa date et son périmètre. Il ne choisit pas lui-même le stade national et ne suppose pas qu'un ancien affichage reste valable. La posture applicable peut évoluer pendant la durée de vie de ce cours : vérifiez les publications officielles du SGDSN et les instructions transmises par la hiérarchie avant une mission ou un événement."""),
    sec('Distinguer plan, régime exceptionnel et mission privée', """Vigipirate est un dispositif de vigilance, de prévention et de protection. Il ne doit pas être confondu avec l'état d'urgence, qui relève d'un régime juridique spécifique, ni avec un état de guerre. Ces cadres obéissent à des décisions et des textes distincts. L'annonce d'un stade Vigipirate élevé ne transforme pas un agent privé en policier et ne rend pas automatiques les palpations, fouilles, contrôles d'identité coercitifs ou interventions hors mission. Chaque acte garde son fondement et ses conditions.

Pour appliquer une mesure, vérifiez quatre éléments : qui l'a décidée, où s'applique-t-elle, à partir de quand et que change-t-elle concrètement dans votre poste ? Une augmentation de vigilance peut conduire à renforcer les transmissions, vérifier certains accès ou modifier une organisation validée. Elle ne justifie pas une sélection du public selon l'origine ou les convictions. Si une consigne contient une demande juridiquement incertaine, demandez une clarification à votre hiérarchie en maintenant les protections déjà licites et nécessaires."""),
    sec('Comprendre l’exposition sans publier les faiblesses', """Un site peut présenter une exposition particulière en raison de sa fréquentation, de sa fonction, de sa valeur symbolique ou de l'activité qu'il héberge. L'évaluation du risque combine la menace, les possibilités d'exposition et les conséquences. L'agent doit connaître les points qui concernent sa mission : accès, flux, moyens d'alerte, zones de protection et personnes à assister. Il ne diffuse pas les détails des dispositifs, les horaires sensibles ou les défauts constatés à des interlocuteurs non autorisés. L'information de sécurité se partage selon le besoin professionnel.

Au briefing, faites préciser les modifications par rapport à la veille : mesure ajoutée, contrôle retiré, accès fermé ou interlocuteur différent. Un support daté évite le mélange de consignes anciennes et nouvelles. Après une modification, vérifiez son application réelle : le panneau a-t-il été remplacé, tous les agents ont-ils reçu le message, le public comprend-il l'orientation ? Le maintien de la vigilance ne consiste pas à multiplier les gestes sans objectif. Il consiste à appliquer de manière cohérente les mesures valides, à détecter leur défaut et à signaler les besoins d'ajustement."""),
    ], example('L’affiche du poste date de deux ans', """Vous prenez votre service et constatez que l'affiche au poste utilise les anciens intitulés de Vigipirate. La nouvelle note reçue par l'entreprise se réfère à la version 2026. Vous demandez la mise à jour de l'affichage et vérifiez la consigne applicable au site, plutôt que de choisir l'intitulé qui vous semble le plus prudent.

Le briefing précise les effets concrets de la posture : contrôles dans leur cadre légal, vigilance sur les accès et chaîne d'alerte. Vous ne créez pas une palpation systématique à partir de l'affiche. La correction est transmise à la relève afin que les équipes disposent d'un langage commun et que le public ne reçoive pas d'explications contradictoires."""),
    ['Repère 2026', 'Sens opérationnel'], [
        ['Vigilance', 'Stade initial du plan.'],
        ['Vigilance renforcée', 'Stade intermédiaire du plan.'],
        ['Alerte attentat', 'Stade le plus élevé, activation encadrée.'],
        ['Consigne du site', 'Mesures datées et adaptées, dans les prérogatives existantes.']],
    ['Les trois stades 2026 remplacent les anciens intitulés.', 'La posture en cours doit être vérifiée sur une source officielle.', 'Vigipirate ne crée pas de pouvoirs de police pour l’agent.', 'Une mesure doit être datée, comprise et effectivement appliquée.'],
    'Deux versions de consigne', 'Le classeur comporte une affiche ancienne et une note récente contradictoire.', [
        question('Quel repère utilisez-vous ?', 'La version officielle actualisée et la consigne validée pour le site.', 'L’affiche la plus alarmante.', 'La version mémorisée lors de la formation initiale.', 'La date et l’autorité de la consigne déterminent son usage actuel.'),
        question('Un collègue propose une fouille forcée au nom de Vigipirate. Que rappelez-vous ?', 'Chaque contrôle conserve ses conditions légales.', 'Le stade élevé autorise tous les contrôles.', 'Seul le volume de fréquentation compte.', 'Le plan ne supprime pas les limites propres à la sécurité privée.'),
        question('Quelle vérification termine la mise à jour ?', 'Que toutes les équipes ont reçu les mesures et l’affichage cohérent.', 'Que le nouveau document est stocké sans information.', 'Que chaque agent choisit sa propre version.', 'Une mise à jour n’est effective que si elle est partagée et appliquée.')], [
        question('Quelle série correspond aux stades du plan 2026 ?', 'Vigilance, vigilance renforcée, alerte attentat.', 'Normal, renforcé, guerre.', 'Vert, orange, rouge sans intitulé officiel.', 'Les intitulés ont été actualisés avec le plan 2026.'),
        question('L’état d’urgence et Vigipirate sont-ils le même dispositif ?', 'Non, ils relèvent de cadres distincts.', 'Oui, ils sont toujours déclenchés ensemble.', 'Oui, seul leur nom change.', 'Le plan de vigilance et le régime juridique d’état d’urgence doivent être distingués.'),
        question('Pourquoi dater une consigne de sécurité ?', 'Pour identifier sa validité et éviter le mélange des versions.', 'Pour remplacer le contrôle des conditions légales.', 'Pour autoriser sa diffusion publique intégrale.', 'La date facilite une application cohérente des mesures actuelles.')])

add('05', 3, 'Reconnaître une découverte dangereuse sans manipuler',
    'Identifier les grandes familles de matériels et de dangers pour transmettre des observations sûres et protéger les lieux.',
    'revision_theorique', [REFLEXES, ATTAQUE], [
    sec('Reconnaître pour alerter, pas pour expertiser', """L'objectif de reconnaissance est de comprendre qu'un matériel ou un contexte peut présenter un danger et d'en donner une description utile. Une arme apparente peut relever de grandes familles, comme une arme courte ou une arme longue ; vous n'avez pas à approcher pour déterminer un modèle. Une réplique peut paraître réelle et un objet ordinaire peut dissimuler un danger. Ne fondez pas votre sécurité sur une certitude visuelle impossible à obtenir. Décrivez la forme générale, la présence et les gestes observés depuis votre position sûre.

Les matières explosives peuvent se présenter sous des aspects très divers. La couleur, l'odeur ou la présence de fils ne permettent ni de confirmer ni d'exclure un danger. Un objet ne doit donc pas être ouvert, secoué, déplacé ou testé. La reconnaissance professionnelle ne consiste pas à apprendre une fabrication ou à analyser un mécanisme. Elle sert à interrompre une approche inutile, à éloigner les personnes et à alerter les services compétents. Les présentations pédagogiques de matériels s'effectuent avec le formateur sur des supports et équipements sécurisés."""),
    sec('Un objet isolé se raisonne dans son contexte', """Un sac sans propriétaire immédiatement visible n'est pas automatiquement un engin dangereux. Le contexte peut toutefois justifier une procédure de découverte : emplacement inhabituel, impossibilité d'identifier son propriétaire sans s'exposer, menace reçue, comportement associé ou autre anomalie. Suivez la consigne du site et demandez le relais prévu. Ne cherchez pas à lever le doute par une manipulation. Une annonce au public, lorsqu'elle est prévue, ne doit pas provoquer une foule autour de l'objet ni dévoiler des informations inutiles.

La mise en sécurité se fait depuis une position protégée : limiter l'accès, orienter les personnes à distance et laisser les autorités déterminer les mesures complémentaires. N'improvisez pas une distance chiffrée universelle ; elle dépend de la situation et des instructions spécialisées. Un poste de sécurité ou une poubelle ne constitue pas un lieu où déplacer l'objet pour « libérer la zone ». Évitez de téléphoner ou d'utiliser un moyen de communication au contact de la découverte ; alertez depuis un endroit sûr suivant les consignes."""),
    sec('Penser aux dangers invisibles et secondaires', """Une odeur anormale, une poudre répandue, un contenant suspect ou plusieurs personnes présentant soudain des symptômes similaires peuvent signaler un danger chimique ou biologique, mais ne permettent pas à l'agent d'en déterminer la nature. Ne touchez pas, ne goûtez pas, ne respirez pas volontairement pour identifier et ne balayez pas la substance. Éloignez-vous de la zone exposée lorsque cela est possible sans accroître le risque, limitez les nouvelles entrées et alertez. Un masque ou un tissu ordinaire ne garantit pas une protection contre un produit dangereux.

Le risque peut persister après un premier événement : objet supplémentaire, structure instable, incendie, fumée ou contamination transportée par des personnes et des objets. Ne rassemblez pas spontanément tout le monde au point habituel si son emplacement n'est pas sûr. Les personnes potentiellement exposées doivent suivre les instructions des secours et ne pas quitter les lieux pour rentrer chez elles ou se rendre seules à l'hôpital en cas de risque contaminant. Votre rôle est de prévenir les nouvelles expositions et de faciliter une prise en charge organisée, sans vous substituer aux équipes spécialisées."""),
    ], example('Un colis découvert près d’une entrée', """Un agent trouve un colis dans un endroit inhabituel après la fermeture d'un hall. Le responsable propose de le déplacer dans la réserve pour rouvrir. Vous maintenez la zone à distance, recueillez les éléments accessibles sans approche et appliquez la chaîne d'alerte. Vous expliquez qu'un déplacement ne lève pas le doute et peut déplacer le risque vers une autre équipe.

Vous décrivez le lieu, l'heure du constat, l'aspect général déjà observé et la présence de personnes à proximité. Vous ne cherchez pas de mécanisme et n'affirmez pas qu'il s'agit d'un explosif. Les services compétents décideront de la suite. La qualité de votre action réside dans l'absence de manipulation et la limitation des nouvelles expositions."""),
    ['Découverte', 'Réflexe attendu'], [
        ['Arme apparente', 'Se protéger et décrire sans approcher pour identifier le modèle.'],
        ['Colis préoccupant', 'Ne pas toucher ni déplacer ; limiter l’accès et alerter.'],
        ['Substance inconnue', 'Éviter contact et dispersion ; demander les secours adaptés.'],
        ['Après un premier incident', 'Conserver la vigilance aux dangers secondaires.']],
    ['L’absence de signe visible n’exclut pas le danger.', 'Ne pas toucher, ouvrir, déplacer ou tester une découverte suspecte.', 'Alerter depuis une position sûre.', 'Le doute se transmet aux spécialistes sans expertise improvisée.'],
    'Le colis gêne la circulation', 'Un colis préoccupant bloque un passage et le client veut le ranger.', [
        question('Quelle action refusez-vous ?', 'Le déplacer dans un autre local pour libérer le passage.', 'Faire éloigner les personnes.', 'Informer le responsable et les services prévus.', 'Déplacer l’objet peut déplacer ou aggraver le risque.'),
        question('Quel message est le plus fiable ?', 'Objet découvert à tel endroit, description générale, contexte et accès protégés.', 'Explosif certain, modèle supposé, sans autre précision.', 'Objet probablement inoffensif parce qu’aucun fil n’est visible.', 'L’alerte doit transmettre les faits sans diagnostic technique infondé.'),
        question('Les autorités demandent de maintenir l’accès fermé. Que faites-vous ?', 'Maintenir la protection et orienter vers les itinéraires autorisés.', 'Rouvrir dès que le client s’impatiente.', 'Organiser une démonstration de l’objet au public.', 'La mesure protège contre une exposition que l’agent n’est pas en mesure d’exclure.')], [
        question('Faut-il connaître le modèle exact d’une arme pour alerter ?', 'Non, une description générale depuis une position sûre suffit.', 'Oui, il faut s’approcher pour lire les marquages.', 'Oui, sinon l’appel sera inutile.', 'La précision ne doit pas être recherchée au prix d’une exposition supplémentaire.'),
        question('L’absence de fils visibles garantit-elle qu’un colis est inoffensif ?', 'Non.', 'Oui, pour un colis fermé.', 'Oui, si le colis est léger.', 'Les apparences ne permettent pas de lever le doute de façon fiable.'),
        question('Une poudre inconnue doit-elle être balayée pour protéger le public ?', 'Non, cela peut la disperser ; il faut isoler et alerter.', 'Oui, avant de demander un avis.', 'Oui, avec un masque ordinaire qui protège de tout.', 'La dispersion et l’exposition doivent être évitées.')])

add('05', 4, 'Entretenir sa vigilance et prévenir la radicalisation violente',
    'Éviter les automatismes de routine et transmettre des faits préoccupants sans stigmatiser des convictions.',
    'revision_theorique', [REFLEXES, 'https://www.dgsi.interieur.gouv.fr/dgsi-a-vos-cotes/lutte-contre-terrorisme/reconnaitre-signes-de-radicalisation-violente', 'https://www.dgsi.interieur.gouv.fr/dgsi-a-vos-cotes/lutte-contre-terrorisme/signaler-personne-radicalisee'], [
    sec('La routine peut rendre une anomalie invisible', """Sur un site connu, l'habitude permet de travailler efficacement, mais peut conduire à ne plus réellement vérifier. Une porte laissée ouverte devient normale, un badge prêté est toléré et une ronde se résume à cocher une case. La vigilance consiste à comparer ce que vous constatez avec ce qui est attendu, puis à traiter l'écart. Ce n'est pas vivre dans la suspicion permanente. C'est rester capable de remarquer un changement et de poser une question factuelle au bon interlocuteur.

À la prise de poste, relisez les événements récents et les consignes temporaires. Pendant la mission, évitez les distractions qui absorbent durablement l'attention, notamment les usages personnels du téléphone. Ne modifiez pas seul les horaires ou les parcours de surveillance dans l'idée de les rendre imprévisibles : les adaptations se décident avec le responsable pour conserver une couverture cohérente et une possibilité de secours. Une action annoncée mais non réalisée doit être signalée, jamais cochée pour donner l'apparence d'une continuité parfaite."""),
    sec('Ne pas confondre croyance, changement personnel et violence', """La radicalisation violente se rapporte à une dynamique qui peut conduire à accepter, soutenir ou préparer la violence. Une conviction religieuse, une opinion politique, une tenue ou un changement de mode de vie ne suffit pas à la caractériser. Les services officiels rappellent qu'un signe isolé ne permet pas de conclure. L'agent ne pose pas un diagnostic de radicalisation et ne crée pas un fichier de convictions. Il peut en revanche transmettre des faits préoccupants dont il a connaissance dans le cadre de sa mission, en distinguant leur origine et leur contexte.

Des propos justifiant explicitement la violence, des menaces concrètes ou des comportements associés à une préparation dangereuse demandent un traitement adapté. Le degré d'urgence compte. Une menace immédiate exige l'appel aux forces de l'ordre par les numéros d'urgence. Une inquiétude sans danger immédiat peut être orientée vers les dispositifs officiels de conseil et de signalement, notamment ceux présentés par la DGSI. La hiérarchie doit être informée selon la procédure, sans que ce relais retarde une alerte urgente. Ne menez pas une enquête privée ni une confrontation idéologique pour obtenir une preuve."""),
    sec('Maintenir une vigilance juste et durable', """La vigilance doit porter sur tous les éléments pertinents de la situation : accès, demandes inhabituelles, comportement, informations reçues et fonctionnement des moyens. Si vous recherchez toujours la même apparence, vous risquez de manquer un fait dangereux présenté sous une forme ordinaire. Les stéréotypes diminuent la qualité de l'observation et portent atteinte aux droits. Une équipe doit pouvoir expliquer pourquoi un fait justifie une action, et non seulement dire qu'une personne « ne lui revient pas ». L'analyse peut être partagée avec un collègue pour limiter les conclusions hâtives.

Le retour d'expérience sert à corriger les habitudes sans installer la peur. Discutez d'une anomalie réelle, de ce qui a permis sa détection et des suites données. Vérifiez que les signalements obtiennent une réponse ; une remontée jamais traitée finit par décourager l'attention. Les temps de pause, les effectifs, l'alternance des tâches et la clarté du briefing influencent la vigilance. Signalez les difficultés de concentration liées aux conditions de travail. Le maintien des compétences passe aussi par une organisation qui permet d'être attentif et de demander un relais avant l'épuisement."""),
    ], example('Une remarque inquiétante au poste', """Un prestataire tient des propos explicites approuvant une attaque puis menace un collègue identifié. Vous rapportez les propos utiles et le contexte exact, sans les attribuer à sa religion ou à son origine. Si la menace paraît immédiate, vous protégez la personne visée et alertez les forces de l'ordre. Vous ne l'invitez pas à un débat pour vérifier ses convictions.

Dans un autre cas, un salarié change simplement de tenue et d'habitudes alimentaires. Aucun fait violent ou menaçant n'est observé. Vous ne transformez pas ce changement en signalement de danger. La différence réside dans les faits et le niveau d'urgence. Les dispositifs officiels peuvent apporter un conseil lorsqu'une inquiétude réelle demeure, sans remplacer une alerte immédiate."""),
    ['Situation', 'Réponse de vigilance'], [
        ['Écart récurrent dans une procédure', 'Le signaler et demander une correction durable.'],
        ['Conviction ou tenue seule', 'Ne pas en déduire une radicalisation violente.'],
        ['Menace concrète immédiate', 'Protéger et alerter les forces de l’ordre.'],
        ['Inquiétude sans urgence', 'Transmettre les faits par le dispositif officiel adapté.']],
    ['La vigilance vérifie les écarts au lieu de cocher par habitude.', 'Une conviction n’est pas une preuve de radicalisation violente.', 'Les menaces concrètes se traitent selon leur urgence.', 'Ne pas mener d’enquête ou de confrontation idéologique privée.'],
    'Une habitude devenue une faille', 'Un badge est prêté régulièrement à des prestataires pour gagner du temps.', [
        question('Comment analyser cette pratique ?', 'Comme un écart à vérifier et à corriger, même s’il est habituel.', 'Comme une autorisation implicite valable grâce à l’ancienneté.', 'Comme une preuve certaine de terrorisme.', 'L’écart doit être traité sans être banalisé ni surqualifié.'),
        question('Quel signalement est utile ?', 'Décrire les prêts constatés et leurs conséquences pour l’identification.', 'Cibler uniquement les personnes d’une origine supposée.', 'Accuser un auteur sans faits.', 'Le signalement doit rendre l’anomalie vérifiable et corrigeable.'),
        question('Le responsable change la procédure. Que vérifiez-vous ?', 'Que les équipes comprennent la nouvelle règle et disposent des moyens de l’appliquer.', 'Que l’ancienne pratique est simplement cachée.', 'Que chaque agent conserve sa propre exception.', 'La vigilance dépend d’une règle cohérente et d’une mise en œuvre réelle.')], [
        question('Un changement de tenue suffit-il à établir une radicalisation violente ?', 'Non, un signe isolé ne permet pas cette conclusion.', 'Oui, s’il est récent.', 'Oui, si un collègue le trouve inhabituel.', 'L’analyse doit porter sur des faits préoccupants et leur contexte, sans stigmatisation.'),
        question('Une menace précise et immédiate nécessite quoi ?', 'Une protection et une alerte urgente adaptées.', 'Un débat idéologique au poste.', 'Une attente de plusieurs jours pour voir si elle se répète.', 'L’urgence se traite par les moyens de protection et d’alerte.'),
        question('Peut-on modifier seul une ronde pour la rendre imprévisible ?', 'Non, l’adaptation doit rester coordonnée et validée.', 'Oui, sans prévenir personne.', 'Oui, en supprimant un secteur au hasard.', 'La couverture du site et la sécurité de l’agent exigent une organisation partagée.')])

add('05', 5, 'Observer, analyser et signaler une situation préoccupante',
    'Construire un signalement fondé sur des faits contextualisés, puis choisir un relais proportionné au danger.',
    'revision_theorique', [REFLEXES, DEONTO], [
    sec('L’observation décrit une action, pas une identité', """Une observation utile répond à des questions concrètes : que fait la personne, où, à quel moment, avec quel effet sur la sécurité et quelles informations sont déjà vérifiées ? Photographier un bâtiment, attendre quelqu'un ou hésiter devant une entrée peut avoir une explication ordinaire. Ce n'est pas une preuve en soi. En revanche, plusieurs faits associés à une demande inhabituelle, à un franchissement interdit ou à une menace peuvent justifier une vérification et un signalement. Le contexte et l'évolution comptent davantage qu'un signe isolé.

La communication non verbale peut renseigner sur une tension ou un changement de comportement, mais elle ne permet pas de lire une intention cachée. L'agitation, la transpiration, l'absence de regard ou une posture inhabituelle ont de nombreuses causes. Ne construisez pas un contrôle sur l'origine, la couleur de peau, une religion supposée ou un handicap. Décrivez les gestes et les demandes réellement observés. Une règle de vigilance juste améliore aussi l'efficacité : elle reste attentive à une anomalie présentée par une personne qui paraît parfaitement familière."""),
    sec('Vérifier sans se mettre en danger ni enquêter', """Lorsque la situation le permet, un contact d'accueil peut lever une incertitude : proposer une aide, demander le service recherché ou vérifier une autorisation selon la procédure. Gardez une attitude professionnelle et ne transformez pas l'échange en interrogatoire. Une réponse imprécise ne suffit pas à conclure à une menace ; elle peut appeler une orientation ou une vérification complémentaire. En cas de danger, ne cherchez pas à obtenir un aveu et n'approchez pas pour compléter votre description. La protection et l'alerte passent avant la précision supplémentaire.

Partagez l'observation avec l'interlocuteur compétent en séparant les éléments vus, les propos entendus et vos incertitudes. Une alerte utile indique aussi ce que vous avez fait : vérification de liste, contact avec le service, fermeture d'un accès ou maintien à distance. N'effectuez pas de recherche intrusive sur les réseaux sociaux et ne suivez pas une personne hors de votre mission pour « confirmer un profil ». L'évaluation spécialisée appartient aux autorités. Votre apport est la qualité, la rapidité et la fiabilité des faits transmis."""),
    sec('Hiérarchiser le signalement', """Le canal dépend de l'urgence. Une menace contre la vie, une arme apparente ou une attaque en cours exige une alerte immédiate depuis une position sûre. Une anomalie sans danger immédiat suit la procédure de remontée interne et le relais approprié. Le signalement ne doit pas être une diffusion générale au public ou à un groupe de collègues non concernés. Il faut un destinataire capable d'agir et, lorsque c'est possible, une confirmation de réception. La confidentialité ne doit pas empêcher l'appel urgent aux services compétents.

Après transmission, continuez à observer seulement dans les limites de votre sécurité et de votre mission. Notez l'évolution, un départ, une réponse d'un service ou un changement de consigne. Corrigez une première information si elle s'avère fausse, sans cacher l'erreur. Les fausses alertes raisonnablement traitées peuvent aussi apporter un enseignement sur l'organisation. Le but n'est pas d'obtenir une confirmation de votre intuition à tout prix. Il est de permettre une décision adaptée et d'éviter aussi bien la banalisation d'un danger que l'escalade provoquée par une accusation infondée."""),
    ], example('Un visiteur cherche un accès technique', """Une personne demande à trois agents différents comment accéder à un local technique, sans pouvoir préciser le service qui l'attend. Vous vérifiez les faits avec les collègues et le service concerné. Vous constatez qu'aucune intervention n'est annoncée et qu'elle a essayé une porte interdite. Ces éléments combinés justifient un signalement factuel.

Vous ne la décrivez pas comme dangereuse à partir de son apparence. Votre message indique les demandes, les lieux, les heures approximatives et la tentative d'accès observée. Vous maintenez la règle d'entrée, contactez le responsable et adaptez la réponse si la situation devient menaçante. La possibilité d'une erreur d'orientation demeure tant que les faits ne permettent pas de conclure autrement."""),
    ['Niveau', 'Information à transmettre'], [
        ['Fait', 'Action ou propos directement observé, daté et localisé.'],
        ['Contexte', 'Autorisation attendue, événement ou anomalie associée.'],
        ['Incertitude', 'Ce qui n’est pas connu ou seulement rapporté.'],
        ['Suite', 'Action réalisée, destinataire prévenu et évolution.']],
    ['Une observation porte sur des faits vérifiables.', 'Un signe corporel isolé ne révèle pas une intention.', 'Une vérification ne doit pas devenir une enquête privée.', 'Le danger détermine l’urgence et le canal.'],
    'Trois demandes inhabituelles', 'Plusieurs collègues rapportent les mêmes demandes d’accès à une zone restreinte.', [
        question('Quelle première étape améliore l’analyse ?', 'Rassembler les faits précis et vérifier l’autorisation annoncée.', 'Choisir l’explication la plus inquiétante sans vérification.', 'Diffuser la photo de la personne à tous vos contacts.', 'Le croisement des faits améliore la décision sans transformer une intuition en certitude.'),
        question('Quel message convient ?', 'Demandes répétées, zone concernée, vérifications et tentative d’accès constatée.', 'Personne suspecte parce que son apparence déplaît.', 'Terroriste certain sans élément de menace.', 'La description doit permettre au destinataire d’évaluer la situation.'),
        question('La personne exhibe un objet ressemblant à une arme. Que changez-vous ?', 'Passer à la protection et à l’alerte urgente depuis une position sûre.', 'Approcher pour identifier le modèle exact.', 'Poursuivre l’entretien pour obtenir sa motivation.', 'Un danger immédiat modifie les priorités ; la précision ne doit pas exposer davantage.')], [
        question('Quel élément est le plus utile dans un signalement ?', 'Une action observée avec lieu, moment et contexte.', 'Une opinion sur le style vestimentaire.', 'Une intuition non expliquée.', 'Les faits contextualisés permettent une décision professionnelle.'),
        question('Faut-il maintenir une accusation si un fait initial est démenti ?', 'Non, il faut corriger l’information transmise.', 'Oui, pour préserver sa crédibilité.', 'Oui, si plusieurs collègues l’ont répétée.', 'La fiabilité exige de mettre à jour les faits, y compris après une erreur.'),
        question('Une vérification autorise-t-elle la recherche intrusive de la vie privée ?', 'Non, elle doit rester dans la mission et le cadre légal.', 'Oui, pour toute personne jugée inhabituelle.', 'Oui, sur un compte personnel de l’agent.', 'La vigilance n’est pas une enquête générale sur les personnes.')])


add('05', 6, 'Faire vivre la culture de sécurité et le retour d’expérience',
    'Vérifier une information, protéger les données du poste et transformer un incident en amélioration concrète.',
    'revision_theorique', [VIGI, REFLEXES, 'https://www.cybermalveillance.gouv.fr/tous-nos-contenus/actualites/dossier-phishing'], [
    sec('S’informer avec une source et une date', """La culture de sécurité se construit entre deux stages MAC. Elle consiste à suivre les informations pertinentes, à comprendre les mesures du site et à réviser les décisions qui protègent. Les sources officielles du SGDSN, du ministère de l'Intérieur, du CNAPS et les consignes validées de l'entreprise servent de repères selon le sujet. Vérifiez la date, le périmètre et l'auteur d'une information. Une fiche ancienne peut être utile pour comprendre un principe, mais ses intitulés, références ou modalités peuvent avoir changé.

Face à une publication alarmante, distinguez information confirmée, commentaire et rumeur. Ne relayez pas une capture sans contexte dans une équipe comme si elle constituait un ordre. Une vidéo peut montrer un autre lieu ou une autre période ; un message peut imiter l'identité d'un responsable. La bonne question est : quelle action ce message justifie-t-il réellement pour notre mission, et qui peut la confirmer ? En cas de danger observable, agissez et alertez ; en cas d'information seule, vérifiez sa fiabilité avant de changer le dispositif."""),
    sec('La sécurité numérique concerne aussi le poste de garde', """Un message d'hameçonnage peut demander une liste de visiteurs, un code, une ouverture d'accès ou le téléchargement d'un document urgent. La qualité du français, un logo connu ou le nom d'un dirigeant ne prouvent pas l'authenticité. Une pression temporelle et une demande inhabituelle doivent provoquer une vérification par un canal connu : numéro déjà enregistré, procédure interne ou service informatique. Ne cliquez pas sur un lien pour vérifier l'identité de celui qui vous l'envoie et ne communiquez pas un mot de passe à un prétendu support.

Les postes et comptes professionnels ne doivent pas être utilisés pour brancher un support inconnu ou installer un logiciel sans autorisation. Une clé USB trouvée n'est pas un objet à ouvrir pour identifier son propriétaire. Si vous avez déjà cliqué, communiqué une information ou constaté une anomalie, prévenez rapidement le service compétent et appliquez sa procédure. Ne cachez pas l'incident et n'improvisez pas une réparation qui pourrait aggraver les effets ou supprimer des traces. La continuité de sécurité se prépare : comment contrôler les accès lorsque le système est indisponible, qui autorise et comment tracer ?"""),
    sec('Transformer un retour d’expérience en action suivie', """Après un incident ou un exercice, reconstituez les faits utiles et les décisions. Qu'est-ce qui a été détecté ? Par qui ? Quel message a permis d'agir ? Quel obstacle a retardé la réponse ? Le but n'est pas de distribuer des reproches, mais de comprendre les conditions concrètes de réussite ou d'échec. Une personne peut avoir appliqué correctement une consigne mal conçue ; une bonne procédure peut être inutilisable faute de matériel. Les propositions doivent donc porter aussi sur l'organisation, les moyens et la formation.

Une amélioration devient réelle lorsqu'elle possède un responsable, une échéance et un moyen de vérifier son application. « Améliorer la communication » est trop vague ; « tester le canal de renfort à chaque prise de poste et signaler les zones sans réception » est observable. Lorsque la procédure change, mettez à jour les supports et le briefing, puis vérifiez que les équipes de nuit et les remplaçants l'ont reçue. La culture de sécurité se reconnaît à cette continuité : signaler, décider, corriger et contrôler, sans attendre le prochain incident grave pour découvrir qu'une action est restée sur le papier."""),
    ], example('Un faux message de la direction', """Le poste reçoit un courriel au nom du directeur demandant d'envoyer immédiatement la liste des visiteurs attendus et les codes d'accès d'un local. Le message indique qu'il faut garder la demande confidentielle. Vous ne répondez pas avec les données et n'utilisez pas le numéro présent dans ce courriel pour le vérifier. Vous contactez le canal interne connu.

Le service confirme une tentative d'usurpation. Vous conservez le message selon la procédure et informez le responsable. Le retour d'expérience conduit à rappeler la règle de vérification des demandes urgentes et à prévoir une alerte commune. L'intérêt n'est pas de féliciter seulement l'agent qui a remarqué l'anomalie, mais de rendre le même réflexe possible pour chaque vacation."""),
    ['Étape', 'Résultat attendu'], [
        ['Vérifier une information', 'Source, date, périmètre et canal identifiés.'],
        ['Protéger les données', 'Aucun code ou fichier sensible transmis sur simple demande inhabituelle.'],
        ['Analyser l’incident', 'Faits, décisions, obstacles et points efficaces compris.'],
        ['Suivre une amélioration', 'Responsable, échéance et vérification concrets.']],
    ['Un logo ou un nom connu ne prouve pas l’authenticité d’un message.', 'Vérifier par un canal déjà connu.', 'Signaler rapidement une erreur numérique sans la masquer.', 'Un retour d’expérience doit aboutir à des actions vérifiables.'],
    'Le courriel urgent', 'Un message au nom du directeur réclame une liste sensible et un code d’accès.', [
        question('Quelle première réaction adoptez-vous ?', 'Ne pas transmettre et vérifier par un canal interne connu.', 'Répondre vite pour respecter l’urgence.', 'Utiliser le lien du message pour confirmer sa légitimité.', 'La vérification doit être indépendante de la demande suspecte.'),
        question('Un collègue a déjà ouvert la pièce jointe. Que faut-il faire ?', 'Alerter rapidement le service compétent et suivre sa procédure.', 'Cacher l’action pour éviter une remarque.', 'Installer un logiciel trouvé en ligne pour nettoyer le poste.', 'Une réaction rapide et encadrée limite les conséquences sans aggraver l’incident.'),
        question('Quelle action concrète peut sortir du débriefing ?', 'Définir le canal de vérification et l’intégrer au briefing de toutes les équipes.', 'Écrire seulement « être plus vigilant ».', 'Interdire tout signalement d’erreur pour ne pas inquiéter le client.', 'Une règle précise, partagée et vérifiable améliore la protection future.')], [
        question('Une clé USB trouvée doit-elle être branchée au poste pour connaître son contenu ?', 'Non, elle suit la procédure de traitement des supports inconnus.', 'Oui, si elle porte un logo connu.', 'Oui, sur le compte d’un collègue.', 'Un support inconnu peut compromettre le poste et les informations.'),
        question('Quelle information caractérise une action de retour d’expérience utile ?', 'Un responsable et un moyen de vérifier sa réalisation.', 'Une formule générale sans suite.', 'Une liste de reproches non documentés.', 'Une amélioration doit pouvoir être suivie concrètement.'),
        question('Pourquoi contrôler la date d’une source ?', 'Pour éviter d’appliquer une règle ou un intitulé dépassé.', 'Pour considérer toute ancienne source comme fausse.', 'Pour remplacer la vérification de son auteur.', 'La date complète l’évaluation de la source et de son périmètre.')])

add('05', 7, 'Se protéger et guider les personnes pendant une attaque',
    'Choisir entre une fuite sûre et une mise à l’abri, puis communiquer des consignes simples sans exposer les personnes.',
    'presentiel_preparation', [ATTAQUE, REFLEXES], [
    sec('La première décision dépend de l’exposition', """Face à une attaque, cherchez d'abord à réduire l'exposition. La fuite est à privilégier lorsqu'un itinéraire permet de s'échapper sans rencontrer le danger immédiat. Utilisez un chemin connu, laissez les affaires et n'approchez pas pour observer ou filmer. L'itinéraire habituel n'est pas forcément sûr : il peut conduire vers l'origine de la menace ou vers un rassemblement exposé. Votre connaissance du site doit aider à identifier une option disponible, sans transformer une hypothèse en garantie. Si l'information est insuffisante, restez attentif aux indices et aux consignes officielles.

Une alarme incendie ne doit pas être déclenchée automatiquement pour répondre à une attaque. Elle pourrait diriger les personnes vers un chemin ou un point de rassemblement dangereux. Appliquez le dispositif d'alerte et de mise en sécurité prévu pour cette situation. Une urgence incendie réelle conserve bien sûr ses exigences propres, qui doivent être articulées avec la menace. La préparation du site doit permettre de distinguer les messages afin que le public comprenne s'il faut évacuer, éviter un secteur ou se mettre à l'abri."""),
    sec('Se cacher lorsque la fuite n’est pas sûre', """Lorsque s'échapper n'est pas possible sans exposition, recherchez une mise à l'abri adaptée. Enfermez-vous ou barricadez l'accès lorsque c'est possible, éloignez-vous des ouvertures et rendez-vous discret. Mettez les téléphones en silencieux, y compris les vibrations, et limitez les sons et lumières visibles. Préservez la possibilité d'alerter depuis cette position. Une cachette ne devient pas sûre parce que la porte est fermée ; continuez à écouter les informations et à suivre les instructions des forces compétentes sans vous exposer pour vérifier chaque bruit.

Les recommandations gouvernementales actualisées mentionnent aussi une résistance en dernier recours lorsque ni la fuite ni la mise à l'abri ne sont possibles et que la vie est directement menacée. Ce caractère exceptionnel ne doit pas être transformé en consigne d'affrontement pour un agent APS. La priorité de ce support reste l'évitement du danger, la protection et l'alerte. Les mises en situation encadrées permettent de travailler les décisions extrêmes et les limites sans enseigner ici de technique de combat ou de neutralisation. Ne poursuivez pas un assaillant et ne quittez pas une protection pour rechercher la confrontation."""),
    sec('Guider sans provoquer un mouvement dangereux', """Donnez des instructions courtes, concrètes et cohérentes : chemin à prendre, secteur à éviter, porte à rejoindre ou nécessité de rester discret. Parlez avec un objectif de protection, sans diffuser un nombre d'assaillants ou une localisation non confirmée. Lorsque cela est possible sans vous exposer, aidez les personnes qui ont besoin d'une orientation particulière, notamment enfants, personnes désorientées ou en situation de handicap. Ne les séparez pas inutilement de leur accompagnant et ne promettez pas qu'un lieu est totalement sûr si vous ne le savez pas.

L'équipe doit éviter les ordres contradictoires et les regroupements improvisés. Un point de rassemblement incendie ne doit pas être utilisé par réflexe si le danger se trouve à proximité. Ne revenez pas chercher un objet oublié et n'autorisez pas un retour simplement parce qu'un bruit a cessé. La fin d'une séquence de tirs ne garantit pas la fin de l'attaque. La levée des mesures relève des instructions compétentes. En présentiel, les exercices permettent de tester la compréhension des messages, les accès réellement utilisables et l'assistance des personnes, sans simuler un danger réel non annoncé au public."""),
    ], example('La sortie habituelle mène vers la menace', """Dans un équipement culturel, des personnes se dirigent spontanément vers l'entrée principale après un bruit violent. Vous disposez d'une information fiable indiquant un danger dans ce secteur. Vous orientez les personnes vers l'option de protection prévue et disponible, sans les envoyer aveuglément vers le point de rassemblement habituel.

Un groupe ne peut pas atteindre une sortie sans exposition. Il se met à l'abri selon la procédure et les téléphones sont rendus silencieux. Vous transmettez la localisation aux secours depuis une position protégée. Un visiteur veut revenir chercher son sac : vous lui demandez de rester protégé. Le raisonnement porte sur l'exposition actuelle et les consignes, pas sur la routine d'une évacuation ordinaire."""),
    ['Situation', 'Décision protectrice'], [
        ['Itinéraire de fuite connu et non exposé', 'S’échapper, laisser les affaires et aider sans se mettre en danger.'],
        ['Fuite dangereuse ou impossible', 'Se mettre à l’abri, fermer ou barricader et rester discret.'],
        ['Personnes à orienter', 'Consignes courtes, cohérentes et adaptées aux besoins.'],
        ['Silence après l’incident', 'Ne pas supposer la fin du danger ; suivre les autorités.']],
    ['La fuite n’est adaptée que si elle réduit l’exposition.', 'L’alarme incendie n’est pas une réponse automatique à une attaque.', 'Une mise à l’abri exige discrétion et alerte adaptée.', 'Ne pas revenir chercher des affaires ni poursuivre un assaillant.'],
    'Deux options de protection', 'Le hall paraît dangereux, mais une sortie secondaire connue est disponible depuis votre zone.', [
        question('Quel critère guide le choix ?', 'L’itinéraire qui réduit l’exposition au danger connu.', 'La sortie utilisée chaque jour, quel que soit le contexte.', 'Le chemin permettant de récupérer les effets personnels.', 'La sécurité du trajet prime sur l’habitude ou la commodité.'),
        question('Pour un groupe sans sortie sûre, que privilégier ?', 'La mise à l’abri adaptée avec discrétion et alerte.', 'Une course obligatoire à travers le hall dangereux.', 'Le déclenchement automatique de l’alarme incendie.', 'Quand la fuite expose davantage, la mise à l’abri peut être l’option protectrice.'),
        question('Le bruit cesse. Peut-on lever seul les mesures ?', 'Non, il faut suivre les informations et consignes compétentes.', 'Oui, le silence prouve que tout est terminé.', 'Oui, si le public veut reprendre l’événement.', 'Le danger peut persister ou se déplacer après une accalmie.')], [
        question('Que faire des affaires personnelles pendant une fuite sûre ?', 'Les laisser pour ne pas retarder la mise en sécurité.', 'Les récupérer avant toute sortie.', 'Revenir les chercher dès que le bruit cesse.', 'Les biens ne doivent pas retarder ou compromettre la protection des personnes.'),
        question('Pourquoi éviter le déclenchement automatique de l’alarme incendie ?', 'Elle peut orienter vers une zone exposée à l’attaque.', 'Parce qu’aucune alerte ne doit jamais être donnée.', 'Parce que les agents privés ne peuvent jamais toucher un dispositif.', 'Il faut utiliser l’alerte adaptée au danger et à l’organisation du site.'),
        question('Quel message au public est adapté ?', 'Une consigne simple sur la direction ou la mise à l’abri.', 'Une rumeur sur les auteurs.', 'Une promesse de sécurité absolue sans information.', 'Une instruction concrète aide à agir sans propager de confusion.')])

add('05', 8, 'Alerter les forces de l’ordre et faciliter leur intervention',
    'Transmettre une alerte exploitable, adopter une attitude identifiable et préserver une zone sans s’exposer.',
    'presentiel_preparation', [ATTAQUE, REFLEXES, 'https://www.service-public.gouv.fr/particuliers/vosdroits/F33953', 'https://info.urgence114.fr/questions-reponses/'], [
    sec('Donner l’information qui permet d’engager la réponse', """Alertez dès que votre position le permet sans vous exposer davantage. Le 17 permet de joindre police ou gendarmerie et le 112 les services d'urgence. Commencez par votre localisation exacte et la nature du danger. Donnez ensuite les faits utiles : ce qui est vu ou entendu, nombre d'auteurs observés sans supposition, description générale, direction de déplacement connue, victimes visibles, zones occupées et accès possibles. Une description peut être utile sans identité ni modèle d'arme. N'approchez pas pour compléter un détail manquant.

Précisez si vous êtes témoin direct ou si l'information vous a été transmise. Un agent caché à proximité n'a pas les mêmes possibilités de communication qu'un collègue en sécurité à l'extérieur. Si parler à voix haute vous met en danger, le 114 peut être contacté par SMS dans les conditions du service ; indiquez le lieu, le danger et votre impossibilité de parler. Écrivez simplement et restez attentif aux demandes du régulateur. Prévenez la hiérarchie dès que possible, sans retarder l'appel urgent aux forces de l'ordre."""),
    sec('Se rendre identifiable et suivre les consignes', """À l'arrivée des forces d'intervention, évitez tout geste brusque et gardez les mains visibles. Ne courez pas vers elles avec un objet à la main. Présentez brièvement votre fonction et obéissez aux consignes, même si elles modifient votre procédure habituelle. Les intervenants doivent d'abord comprendre la menace et sécuriser la situation. Le fait d'être en uniforme privé ne suffit pas à rendre vos intentions évidentes dans la confusion. Votre calme, vos mains visibles et une information concise facilitent leur travail.

Un point de contact du site peut fournir les plans, accès, clés ou informations utiles lorsque les autorités le demandent. Cette transmission doit se faire en sécurité et par une personne identifiée. Ne pénétrez pas avec les unités dans une zone d'attaque, n'improvisez pas de reconnaissance et ne publiez pas leur position ou leur progression. Les centres opérationnels de police ou de gendarmerie organisent et coordonnent les moyens ; l'agent privé apporte la connaissance du site dans les limites demandées. L'information utile ne doit pas se perdre dans des conversations parallèles."""),
    sec('Préserver une zone et anticiper les dangers secondaires', """Limiter les accès peut empêcher des personnes de rejoindre une zone dangereuse. Cette mesure doit être prise depuis une position sûre, avec les moyens et consignes applicables. Ne vous placez pas au contact d'un danger pour matérialiser une limite. Les autorités définissent et ajustent les périmètres nécessaires. Votre rôle peut être d'orienter les personnes vers un point autorisé, de garder un passage pour les secours ou de transmettre la localisation d'un groupe à l'abri. Aucun périmètre improvisé ne doit enfermer des personnes dans le danger.

Après une première attaque, la vigilance demeure : menace secondaire, objet suspect, bâtiment endommagé, véhicule en mouvement ou afflux de proches. Ne considérez pas une zone comme sûre sur le seul fait que l'auteur apparent est parti. Respectez les restrictions d'accès, préservez les éléments utiles et empêchez les attroupements dans les limites de votre mission. Les personnes blessées ou choquées sont orientées selon les secours. Une reprise d'activité ou une réouverture ne relève pas d'une initiative de l'agent. Le relais de consignes doit être tracé pour que toutes les équipes sachent qui a décidé quoi et à quel moment."""),
    ], example('Vous êtes caché et ne pouvez pas parler', """Vous vous êtes mis à l'abri avec trois personnes. Parler révélerait votre position. Vous adressez un SMS au 114 avec l'adresse, le bâtiment, l'étage, la pièce, le danger observé et le fait que vous ne pouvez pas parler. Vous n'envoyez pas un message vague comme « venez vite » sans localisation.

Lorsque les forces de l'ordre vous donnent des consignes de sortie, vous gardez les mains visibles et ne prenez pas d'objet qui pourrait être mal interprété. Vous indiquez la présence des autres personnes et une éventuelle difficulté de déplacement. Vous ne cherchez pas à guider spontanément les unités à travers une zone que vous n'avez pas pu vérifier. Votre contribution porte sur les faits et la connaissance du lieu."""),
    ['Moment', 'Information ou comportement attendu'], [
        ['Alerte initiale', 'Localisation, danger, faits, victimes et accès connus.'],
        ['Impossible de parler', 'SMS au 114 avec informations claires et position.'],
        ['Arrivée des forces', 'Mains visibles, gestes calmes et respect des consignes.'],
        ['Après l’attaque', 'Maintenir les limites d’accès et la vigilance aux risques secondaires.']],
    ['La localisation précise doit arriver tôt dans l’alerte.', 'Ne pas s’exposer pour compléter une description.', 'Les mains visibles et les consignes suivies facilitent l’intervention.', 'La disparition apparente de l’auteur ne lève pas le danger.'],
    'Le relais avec les intervenants', 'Après votre alerte, les forces de l’ordre arrivent pendant que le public cherche à sortir.', [
        question('Comment vous présentez-vous ?', 'Mains visibles, gestes calmes et fonction annoncée brièvement.', 'En courant vers elles avec une radio levée brusquement.', 'En donnant immédiatement des ordres aux unités.', 'Une attitude lisible évite une confusion dans une situation dangereuse.'),
        question('Un intervenant demande un plan du site. Que faites-vous ?', 'Le fournir par le point de contact sûr et selon les consignes.', 'Le publier sur un réseau social pour tous les intervenants.', 'Entrer seul dans la zone d’attaque pour récupérer un document non indispensable.', 'L’information utile doit être transmise sans nouvelle exposition ni diffusion incontrôlée.'),
        question('Des visiteurs veulent revenir après une accalmie. Quelle réponse convient ?', 'Maintenir la restriction jusqu’aux instructions compétentes.', 'Rouvrir parce que la file devient difficile.', 'Laisser passer ceux qui promettent d’être prudents.', 'La levée des mesures ne dépend pas de l’impatience du public.')], [
        question('Quelle information doit être donnée au début d’une alerte ?', 'La localisation exacte et la nature du danger.', 'Le nom de tous les collègues de la vacation.', 'Une théorie sur le mobile des auteurs.', 'Les moyens d’intervention doivent savoir où se rendre et à quel danger répondre.'),
        question('Que faire si parler à voix haute vous expose ?', 'Contacter le 114 par SMS dans les conditions du service.', 'Attendre systématiquement de pouvoir crier.', 'Publier votre cachette publiquement.', 'Le 114 permet une alerte écrite lorsque la parole est impossible ou dangereuse.'),
        question('Pourquoi éviter de publier la progression des forces ?', 'Pour ne pas compromettre leur intervention ni la sécurité des personnes.', 'Parce qu’aucune information ne doit être donnée aux secours.', 'Parce que l’agent privé dirige seul l’opération.', 'La diffusion publique d’informations opérationnelles peut créer un risque supplémentaire.')])

add('05', 9, 'Reconnaître les blessures liées à une attaque',
    'Identifier des signes de gravité et transmettre un bilan factuel sans diagnostic ni geste invasif.',
    'revision_theorique', [BASE, INRS, ATTAQUE], [
    sec('Le mécanisme oriente la vigilance', """Après une attaque, le type d'événement peut faire craindre des blessures particulières, sans permettre de connaître toutes les lésions. Un projectile peut provoquer une plaie avec des atteintes internes non visibles. Une explosion peut associer souffle, projections, brûlures, chute et écrasement. Une personne capable de marcher peut présenter une blessure sérieuse. Votre rôle est de transmettre les circonstances connues et les signes observés, pas de conclure qu'une victime est indemne parce qu'elle parle ou qu'une plaie semble petite.

Le souffle d'une explosion, parfois nommé blast, peut affecter des organes sans marque extérieure évidente. Des difficultés respiratoires, une douleur thoracique, des troubles auditifs, une confusion ou une altération progressive de l'état doivent être signalés. Le fait de connaître le terme ne vous autorise pas à diagnostiquer une lésion. Indiquez si la personne se trouvait près de l'explosion, ce qu'elle rapporte et ce qui change. Ces informations aident les secours à organiser l'évaluation, même lorsque vous ne pouvez pas décrire précisément la distance ou la puissance de l'événement."""),
    sec('Repérer les urgences visibles et leurs limites', """Un saignement abondant est une urgence qui doit être traité par les gestes appris dès que la situation permet de secourir en sécurité. D'autres signes peuvent évoquer une dégradation : pâleur, faiblesse, soif exprimée, trouble de conscience ou respiration anormale. Ils ne suffisent pas à localiser une hémorragie interne. Une plaie thoracique peut s'accompagner d'une difficulté respiratoire ; le pneumothorax désigne une présence d'air autour du poumon et relève d'une prise en charge médicale. Cette notion sert à comprendre la gravité possible, jamais à entreprendre une décompression ou un geste invasif.

Une brûlure, un membre douloureux ou une plaie avec objet fiché appellent les précautions correspondantes. N'explorez pas la plaie, ne retirez pas un objet fiché et ne tentez pas de remettre un membre en place. La douleur peut être masquée par le stress ; la présence d'une blessure évidente ne doit pas faire oublier la conscience et la respiration. Les vêtements ne sont examinés ou adaptés que dans le cadre nécessaire aux gestes de secours maîtrisés et dans le respect de la dignité, en évitant toute manipulation supplémentaire sans utilité."""),
    sec('Surveiller, protéger et transmettre', """La sécurité de la zone reste déterminante. Ne rejoignez pas une victime au milieu d'une menace active sans possibilité de protection. Lorsque les soins peuvent être engagés, protégez-vous contre le contact avec le sang selon les moyens disponibles, appliquez vos compétences et suivez la régulation. Préservez la victime du froid et des intempéries, rassurez-la et surveillez son état. L'exposition, des vêtements mouillés ou l'immobilité peuvent aggraver le refroidissement même lorsqu'il ne fait pas très froid. Ne donnez pas à boire ou à manger par habitude en attendant les secours.

Un bilan utile comporte la localisation, le nombre de victimes, le mécanisme connu, la conscience, la respiration, les saignements, les autres signes et les gestes réalisés. Précisez ce qui est vu et ce qui est déclaré par la victime. Une évolution doit être transmise rapidement. En présence de plusieurs personnes, n'attribuez pas une priorité médicale définitive à partir du niveau de plainte ou de l'apparence ; les secours organisent le triage. Vous pouvez contribuer en décrivant, en guidant et en maintenant la protection. Les activités de cette leçon vérifient la reconnaissance ; les gestes de secours se travaillent dans les ateliers encadrés."""),
    ], example('La victime marche mais respire difficilement', """Après une explosion, une personne rejoint le point protégé par ses propres moyens. Elle dit qu'elle va bien, puis décrit une douleur thoracique et semble essoufflée. Vous ne la laissez pas repartir sur le seul constat qu'elle marche. Vous alertez les secours avec le mécanisme et les signes, la mettez au repos dans une position adaptée aux consignes et surveillez l'évolution.

Vous ne cherchez pas à nommer une lésion interne ni à réaliser un geste technique non appris. Le message indique la proximité rapportée de l'explosion, la conscience, la difficulté respiratoire et le début des symptômes. Cette précision est plus utile qu'un diagnostic supposé. Vous protégez également la personne des regards et du froid jusqu'au relais."""),
    ['Blessure ou mécanisme', 'Information utile aux secours'], [
        ['Projectile', 'Localisation visible, saignement et circonstances connues.'],
        ['Explosion / souffle', 'Exposition rapportée, respiration, conscience et évolution.'],
        ['Plaie thoracique', 'Difficulté respiratoire et signes observés, sans geste invasif.'],
        ['Brûlure / traumatisme', 'Zone atteinte, douleur, mécanisme et précautions déjà prises.']],
    ['Une petite plaie ou une marche possible ne garantit pas l’absence de gravité.', 'Une explosion peut provoquer des lésions non visibles.', 'Observer un signe ne signifie pas poser un diagnostic.', 'Aucun objet fiché retiré, aucune exploration ou décompression improvisée.'],
    'Des signes apparaissent après coup', 'Une personne évacuée après une explosion devient progressivement essoufflée.', [
        question('La capacité à marcher au départ est-elle rassurante à elle seule ?', 'Non, une lésion grave peut ne pas être immédiatement visible.', 'Oui, elle exclut toute atteinte interne.', 'Oui, elle dispense d’un avis médical.', 'Le mécanisme et l’évolution doivent être pris en compte.'),
        question('Quelle information transmettez-vous ?', 'L’exposition connue, les symptômes et leur évolution.', 'Un diagnostic certain de pneumothorax sans examen médical.', 'Seulement le fait qu’elle est arrivée debout.', 'Les faits et signes permettent aux secours d’évaluer la situation.'),
        question('Quel geste doit être exclu de votre initiative ?', 'Une décompression thoracique ou toute intervention invasive.', 'La surveillance de la respiration.', 'La protection contre le froid.', 'La connaissance d’un risque ne crée pas une compétence médicale invasive.')], [
        question('Que peut provoquer une explosion sans marque extérieure évidente ?', 'Des lésions liées au souffle.', 'Uniquement une frayeur sans conséquence.', 'Toujours une blessure immédiatement visible.', 'Le mécanisme peut entraîner des atteintes internes qui nécessitent une évaluation.'),
        question('Comment rendre compte d’une plainte de douleur ?', 'En précisant qu’elle est rapportée par la victime.', 'En la transformant en diagnostic certain.', 'En l’ignorant si aucune plaie n’est visible.', 'La distinction entre plainte et observation améliore le bilan.'),
        question('Qui organise le triage médical de plusieurs victimes ?', 'Les services de secours compétents.', 'L’agent selon le volume des cris uniquement.', 'Le client selon l’ordre d’arrivée sur le site.', 'L’agent fournit des observations et contribue à la protection sans établir seul une priorité médicale définitive.')])

add('05', 10, 'Secours après attaque : préparer les gestes et le bilan',
    'Comprendre les priorités du secours sous menace, les limites des matériels et les informations à remettre aux secours.',
    'presentiel_preparation', [INRS, SECOURS, 'https://www.inrs.fr/demarche/organisation-secours/materiel-premiers-secours', 'https://www.service-public.gouv.fr/particuliers/vosdroits/F33959'], [
    sec('Le secours ne doit pas créer une nouvelle victime', """Les notions de secours en contexte d'attaque associent la prise en compte de la menace et les gestes d'urgence. Avant d'approcher, identifiez si le danger est toujours actif et si la victime peut être atteinte sans exposition supplémentaire. Ne quittez pas une position protégée pour réaliser un examen dans une zone dangereuse. L'alerte, l'indication de la localisation et l'assistance depuis un endroit sûr peuvent être les premières actions possibles. L'agent ne se substitue pas aux équipes spécialisées dans une intervention sous menace.

Un dégagement d'urgence ne se justifie que pour soustraire une personne à un danger réel, vital, immédiat et non contrôlable, avec une possibilité d'accès et de retrait compatible avec votre sécurité. Il ne sert pas à regrouper toutes les victimes pour la commodité du bilan. Les techniques et limites doivent être démontrées et exercées avec le formateur. Avant tout déplacement nécessaire, pensez au lieu de protection accessible ; déplacer une personne sans destination plus sûre peut aggraver la situation. Dès qu'un relais compétent arrive, suivez ses consignes et fournissez les informations utiles."""),
    sec('Connaître les matériels sans improviser leur emploi', """Le programme MAC prévoit une sensibilisation aux matériels de contrôle d'une hémorragie, dont pansement compressif, pansement hémostatique et garrot tourniquet. Leur présentation vise à connaître leur fonction, leurs indications et leurs limites. Une compression efficace reste à surveiller. Un pansement compressif peut relayer une compression dans les conditions apprises ; un tourniquet répond à des indications précises sur un membre. Un pansement hémostatique ne doit pas conduire à explorer ou combler une plaie sans formation et cadre adaptés. La seule présence d'un kit ne garantit pas une compétence d'utilisation.

Les gestes se réalisent conformément à la formation reçue et aux instructions des secours. Ne desserrez pas un garrot posé ; transmettez son heure de pose et laissez-le identifiable aux intervenants. Ne retirez pas un objet fiché et n'effectuez aucun geste invasif. Vérifiez l'efficacité de l'action, continuez la surveillance et protégez la victime contre le refroidissement. Le matériel doit être accessible, connu, entretenu et complet selon l'organisation du site. Un inventaire théorique ne suffit pas si personne ne sait où le trouver pendant la vacation de nuit."""),
    sec('Alerter les secours et organiser le relais humain', """Le bilan doit permettre aux secours de préparer leur intervention : lieu exact, accès sûr, menace persistante ou non confirmée, nombre de victimes et signes prioritaires. Pour chaque personne examinée, précisez conscience, respiration, saignement, autres blessures visibles et gestes effectués. Ajoutez l'évolution et les horaires utiles, notamment ceux des actions importantes. Donnez les informations que vous connaissez sans retarder l'appel pour obtenir une fiche parfaite. L'appel peut être complété ; une alerte tardive ne se rattrape pas par une description plus longue.

Lorsque plusieurs intervenants sont présents, répartissez les rôles : gestes, alerte, accueil des secours, protection des autres personnes et transmission. Les victimes valides peuvent être orientées selon les consignes sans être envoyées seules hors du dispositif. Les personnes choquées et les agents impliqués peuvent avoir besoin d'un soutien ; les dispositifs médico-psychologiques et d'aide aux victimes relèvent d'interlocuteurs compétents. Protégez leur intimité et évitez les images d'incident. Une éventuelle dispense du module général de sept heures ne supprime pas les objectifs de secours du module terrorisme. La réussite des activités en ligne ne valide pas ces mises en pratique ni le stage MAC réglementaire."""),
    ], example('Une victime dans une zone qui reste exposée', """Une personne blessée est visible dans une zone où le danger n'est pas écarté. Depuis votre protection, vous alertez et donnez sa localisation, les accès connus et les signes que vous pouvez observer sans vous exposer. Vous ne traversez pas automatiquement la zone pour remplir un bilan plus détaillé. La possibilité d'une aide directe dépend de la sécurité et des consignes.

Quand la prise en charge devient possible, vous appliquez les gestes maîtrisés et transmettez les actions. Un collègue prépare l'accueil des secours pendant qu'un autre préserve l'espace. Si un garrot a été posé, son heure est communiquée et personne ne le desserre. Le formateur vérifiera en atelier le raisonnement, le matériel et les gestes ; le cas numérique entraîne ici les priorités et la qualité du relais."""),
    ['Priorité', 'Point de contrôle'], [
        ['Menace', 'Approche et retrait possibles sans exposition supplémentaire ?'],
        ['Geste', 'Indication reconnue, compétence acquise et efficacité surveillée ?'],
        ['Matériel', 'Accessible, connu et utilisé dans ses limites ?'],
        ['Bilan', 'Lieu, danger, victimes, signes, gestes, horaires et évolution transmis ?']],
    ['La protection reste la première condition d’un secours direct.', 'Un dégagement d’urgence exige un danger qui le justifie.', 'Les matériels nécessitent une formation et un emploi adapté.', 'La dispense SST ne dispense pas du secours prévu dans le module terrorisme.', 'Les mises en pratique et la validation réglementaire restent distinctes du parcours numérique.'],
    'Le kit est disponible, la menace ne l’est pas encore', 'Vous possédez un kit de secours, mais la victime se trouve dans une zone non sécurisée.', [
        question('La présence du kit autorise-t-elle une approche immédiate ?', 'Non, l’exposition et la sécurité doivent d’abord être évaluées.', 'Oui, le matériel protège contre la menace.', 'Oui, pour toute personne titulaire du SST.', 'Les compétences et le matériel ne suppriment pas un danger actif.'),
        question('Un garrot a été posé par un intervenant formé. Que transmettez-vous ?', 'L’heure de pose et l’évolution, sans le desserrer.', 'L’intention de le desserrer régulièrement.', 'Seulement la marque du kit.', 'Les secours ont besoin de connaître la pose ; le desserrage ne doit pas être improvisé.'),
        question('Un stagiaire est dispensé du module général de secours. Que reste-t-il à suivre ?', 'Les objectifs de secours du module terrorisme et leurs pratiques requises.', 'Aucun contenu de secours, quel que soit le module.', 'Uniquement le QCM, qui valide tous les gestes.', 'La dispense du module général ne supprime pas les objectifs spécifiques du module terrorisme.')], [
        question('À quoi sert un dégagement d’urgence ?', 'À soustraire à un danger réel, vital, immédiat et non contrôlable lorsque cela est possible en sécurité.', 'À aligner les victimes pour faciliter le comptage.', 'À déplacer toute personne vers le poste par habitude.', 'Le déplacement doit répondre à un danger précis et permettre une meilleure protection.'),
        question('Que prouve la présence d’un pansement hémostatique dans un kit ?', 'Sa disponibilité, pas une compétence automatique pour l’utiliser.', 'L’autorisation d’explorer toute plaie.', 'Une qualification médicale de l’agent.', 'Le matériel doit être associé à une formation et à un cadre d’emploi adaptés.'),
        question('Faut-il attendre un bilan parfaitement complet avant l’alerte ?', 'Non, appeler rapidement puis compléter les informations.', 'Oui, même si la victime se dégrade.', 'Oui, jusqu’à l’arrivée du responsable du client.', 'Une alerte précoce permet d’engager les moyens ; elle peut être actualisée.')])


if __name__ == '__main__':
    output = Path(__file__).resolve().parents[1] / 'elearning_native' / 'mac_aps' / 'lessons.json'
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(json.dumps({'schema_version': 1, 'lessons': LESSONS}, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    print(f'{len(LESSONS)} lessons written to {output}')
